/* 10వ తరగతి – te2 పూర్తి పాఠాలు (tools/split/split_class10.py) */
((window.RAAY_TBF=window.RAAY_TBF||{})[10]=window.RAAY_TBF[10]||{})["te2"]=[{"id":"sl1","no":1,"t":"భాగవత రత్నాలు","m":[6],"ty":"పద్యం","th":"విలువలు","by":"బమ్మెర పోతన","sum":"పోతన ఆంధ్ర మహాభాగవతం నుండి ఏరిన నీతి పద్యాలు ఇవి. చదువుకోనివాడు అజ్ఞాని; చదివితే మంచిచెడుల వివేకం, చతురత కలుగుతాయి – కాబట్టి అందరూ చదువుకోవాలని హిరణ్యకశిపుడు ప్రహ్లాదుడితో అంటాడు. బలవంతులకు, బలహీనులకు, బ్రహ్మాది దేవతలకు, సకల ప్రాణులకు బలమైన ఆ భగవంతుడే నాకూ బలం అని ప్రహ్లాదుడి జవాబు. ఇతరులకు మేలు చేసేవాడు పంచభూతాలకూ ప్రియుడు; పరహితమే పరమ ధర్మం, పరహితునికి ఎదురులేదు. కష్టాలు, పేదరికం వచ్చినా, ప్రాణం పోయినా మానధనులు మాట తప్పరు (బలి చక్రవర్తి). అన్నమో, మజ్జిగో, నీళ్ళో, కూరో – ఉన్నంతలో అతిథులకు పెట్టనివారు ధనవంతులైనా దరిద్రులే. అతిథులను భక్తితో పూజించి సత్కరించే సజ్జనులకు శాశ్వత కీర్తి లభిస్తుంది.","pts":["కవి: బమ్మెర పోతన (15వ శతాబ్దం) – ఓరుగల్లు దగ్గర బమ్మెర గ్రామం; సహజకవిగా సుప్రసిద్ధుడు; భక్తరసామృతంగా భాగవతాన్ని మలిచాడు.","రచనలు: ఆంధ్ర మహాభాగవతం, నారాయణ శతకం, భోగినీ దండకం, వీరభద్ర విజయం.","తెలుగు నుడికారం, శబ్దాలంకారాల ప్రయోగంలో సిద్ధహస్తుడు.","భాగవతం – పురాణం; వ్యాసుని సంస్కృత భాగవతానికి పోతన తెలుగు అనువాదం (స్వేచ్ఛానువాదం).","\"పలికెడిది భాగవతమట, పలికించెడివాడు రామభద్రుండట\" – పోతన భక్తి.","విలువలు: చదువు, దైవబలం, పరహితం, మాటనిలకడ (సత్యం), అతిథి సత్కారం."],"w":[["అజ్ఞుడు","తెలివిలేనివాడు"],["సదసద్వివేకం","మంచిచెడుల విచక్షణ"],["చతురత","నేర్పు"],["ఆర్యులు","పెద్దలు, గురువులు"],["బలయుతులు","బలవంతులు"],["అసురేంద్రుడు","రాక్షస రాజు"],["పరహితం","ఇతరుల మేలు"],["భూతపంచకం","పంచభూతాలు"],["లేమి","పేదరికం"],["మానధనులు","అభిమానమే ధనంగా గలవారు"],["తక్రం","మజ్జిగ"],["తోయం","నీరు"],["శాకం","కూరగాయ"],["శాశ్వతకీర్తి","ఎప్పటికీ నిలిచే పేరు"],["ధరణి","భూమి"]],"gr":{"t":"భాషాంశాలు","p":["భాషాభాగాలు: నామవాచకం (ప్రహ్లాదుడు, క్షమ), సర్వనామం (మన, నీవు), విశేషణం (సమానులు, ముఖ్యం), క్రియ (చదువు, ఆలోచించు), అవ్యయం (ఆహా!).","విభక్తి ప్రత్యయాలు: డు,ము,వు,లు (ప్రథమ); నిన్,నున్,లన్,గూర్చి,గురించి (ద్వితీయ); చేతన్,చేన్,తోడన్,తోన్ (తృతీయ); కొఱకున్,కై (చతుర్థి); వలనన్,కంటెన్,పట్టి (పంచమి); కిన్,కున్,యొక్క,లోన్,లోపలన్ (షష్ఠి); అందున్,నన్ (సప్తమి).","కర్తరి వాక్యం: కర్త ప్రధానం – \"రేష్మ ప్రార్థన చదివింది\". కర్మణి వాక్యం: కర్మ ప్రధానం, \"చేత…బడు\" – \"రేష్మచేత ప్రార్థన చదువబడింది\".","ప్రకృతి–వికృతి: ఆర్య–అయ్య, ధర్మం–దమ్మం, కీర్తి–కీరితి."]},"qa":[["చదువు గురించి పద్యం ఏమి చెబుతుంది?","చదువనివాడు అజ్ఞుడు; చదివితే మంచిచెడుల వివేకం, నేర్పు కలుగుతాయి – అందరూ చదువుకోవాలి."],["ప్రహ్లాదుడికి బలం ఎవరు?","బలవంతులకు, బలహీనులకు, బ్రహ్మాది దేవతలకు, సకల ప్రాణులకు బలమైన భగవంతుడే."],["పరమ ధర్మం ఏది?","పరహితం (ఇతరులకు మేలు చేయడం)."],["మానధనులు ఏమి చేయరు?","ఎన్ని కష్టాలు వచ్చినా ఇచ్చిన మాట తప్పరు."],["ధనవంతులు కూడా దరిద్రులు ఎప్పుడు?","ఉన్నంతలో అతిథులకు పెట్టకపోతే."],["శాశ్వత కీర్తి ఎవరికి?","అతిథులను భక్తితో పూజించి సత్కరించే సజ్జనులకు."]],"act":"\"చదువు\", \"పరహితం\", \"సత్యం\" గొప్పదనం తెలిపే పద్యాలను సేకరించి సంకలనంగా తయారుచేసి తరగతిలో ప్రదర్శించండి.","kn":"సూక్తి: సంపదలు, ప్రాణం, జీవితం, యౌవనం – ఇవన్నీ అస్థిరాలే; సర్వం అస్థిరమైన ఈ లోకంలో ధర్మమొక్కటే స్థిరమైనది.","qz":[["\"భాగవత రత్నాలు\" కవి?","బమ్మెర పోతన","నన్నయ","తిక్కన","శ్రీనాథుడు"],["పోతన బిరుదు/ప్రసిద్ధి?","సహజకవి","కవిసార్వభౌముడు","ఆదికవి","కవిబ్రహ్మ"],["పోతన రచన కానిది?","శృంగార నైషధం","నారాయణ శతకం","భోగినీ దండకం","వీరభద్ర విజయం"],["\"చదువనివాడజ్ఞుండగు\" – అన్నది ఎవరు ఎవరితో?","హిరణ్యకశిపుడు ప్రహ్లాదునితో","ప్రహ్లాదుడు హిరణ్యకశిపునితో","బలి వామనునితో","శుక్రుడు బలితో"],["చదివితే కలిగేది?","సదసద్వివేక చతురత","ధనం మాత్రమే","గర్వం","బలం"],["పరమ ధర్మం ఏది?","పరహితం","ధనార్జన","యుద్ధం","నిద్ర"],["మాట తిరుగలేనివారు?","మానధనులు","ధనవంతులు","బలవంతులు","రాజులు"],["\"తక్రం\" అంటే?","మజ్జిగ","నీరు","అన్నం","కూర"],["అతిథులకు పెట్టనివారు?","కలిగి లేనివారు (దరిద్రులు)","దాతలు","సజ్జనులు","కీర్తిమంతులు"],["శాశ్వత కీర్తి పొందేది?","అతిథులను పూజించే సజ్జనులు","ధనవంతులు","యుద్ధ వీరులు","పండితులు"],["\"లేమి\" అంటే?","పేదరికం","సంపద","బలం","కీర్తి"],["\"భూతపంచకం\" అంటే?","పంచభూతాలు","ఐదుగురు దయ్యాలు","ఐదు ప్రాణులు","పంచాంగం"],["ధర్మం – వికృతి?","దమ్మం","దరమం","దర్మ","దొమ్మం"],["\"వంట నలునిచేత చేయబడింది\" – ఏ వాక్యం?","కర్మణి","కర్తరి","ప్రశ్నార్థకం","ఆశ్చర్యార్థకం"]],"wb":{"mis":"కర్మణి వాక్యంలో కర్తకు \"చేత\", క్రియకు \"బడు\" చేరతాయి; కర్తరిలో కర్త నేరుగా ఉంటుంది. \"ఆహా!\" లాంటి ఆశ్చర్య పదాలు అవ్యయాలు.","qz":[["\"ఆహా! క్షమ ఎంత గొప్పది\" – ఆహా ఏ భాషాభాగం?","అవ్యయం","నామవాచకం","క్రియ","సర్వనామం"],["\"మన బతుకొక్కటే ముఖ్యం కాదు\" – \"మన\"?","సర్వనామం","విశేషణం","క్రియ","అవ్యయం"],["\"సీత డబ్బు__ బ్యాంక్__ దాచుకుంది\"","ను, లో","తో, కి","చేత, వలన","కొరకు, యొక్క"],["\"రేష్మ ప్రార్థన చదివింది\" – కర్మణి?","రేష్మచేత ప్రార్థన చదువబడింది","ప్రార్థన రేష్మను చదివింది","రేష్మ ప్రార్థనను చదువుతుంది","రేష్మకు ప్రార్థన చదవబడదు"],["\"సునీల్‌చేత పాఠం చెప్పబడింది\" – కర్తరి?","సునీల్ పాఠం చెప్పాడు","పాఠం సునీల్‌ను చెప్పింది","సునీల్‌కు పాఠం చెప్పారు","సునీల్ పాఠం విన్నాడు"],["కీర్తి – వికృతి?","కీరితి","కీరి","కిత్తి","కీర్తము"]],"pg":"1–7","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":9,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించి చెప్పండి (పుట 1)","అవగాహన – ప్రతిస్పందన (పుట 5)","వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 6)","వ్యాకరణాంశాలు; ప్రాజెక్టు (పుట 7)"]},"tg":[["చదవండి – ఆలోచించి చెప్పండి (పుట 1)",["1) భాగవతం చెప్పేది పోతన, చెప్పించేది శ్రీరాముడు; దీన్ని చెబితే భవబంధాలు (సంసార బంధం) తొలగుతాయి – కాబట్టి భాగవతమే చెబుతానని కవి భక్తి తెలుస్తుంది 2) బమ్మెర పోతన 3) ఆంధ్ర మహాభాగవతం 4) శ్రీమహావిష్ణువు అవతారాలు, ఆయన భక్తుల (ప్రహ్లాదుడు, గజేంద్రుడు, బలి, ధ్రువుడు, శ్రీకృష్ణుడు) కథలు"]],["అవగాహన – ప్రతిస్పందన (పుట 5)",["1. అ) ఉదా: మహాత్మా గాంధీ (సత్యం, అహింస), బలి చక్రవర్తి, కర్ణుడు (దానం), శిబి చక్రవర్తి, మదర్ థెరిసా (సేవ), డా. ఏపీజే అబ్దుల్ కలాం – తమ మంచి పనులతో శాశ్వత కీర్తి పొందారు ఆ) చదువుకోవాలి; ఆ దేవుడే అందరికీ బలం; పరహితమే పరమధర్మం; మానధనులు మాట తప్పరు; ఉన్నంతలో అతిథులకు పెట్టాలి; అతిథులను సత్కరించేవారికి శాశ్వత కీర్తి","2. ✓ సరైనవి: అ) ఆపదలో ఉన్నవాళ్ళను మిత్రుడు ఆదుకోవాలి ఆ) మంచిపనులను ప్రోత్సహించేవాడే మిత్రుడు ఇ) మిత్రుడు సద్గుణాలను పెంపొందిస్తాడు ఈ) పై పేరా ఉత్తమమిత్రుని లక్షణాలను చెబుతుంది","3. అ) చదువనివాడు అజ్ఞుడు; చదివితే మంచిచెడుల వివేకం, చతురత కలుగుతాయి; అందరూ చదువుకోవాలి; గురువుల దగ్గర చదువుకోవాలి ఆ) పరహితం చేసేవాడు పంచభూతాలకు, సకల ప్రాణులకు హితుడవుతాడు; పరహితమే పరమధర్మం; పరహితునికి ఎదురు ఉండదు ఇ) తమకు ఉన్నంతలో అన్నమో, మజ్జిగో, నీళ్ళో, కూరో అతిథులకు పెట్టకపోతే ధనవంతులు కూడా దరిద్రులే"]],["వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 6)",["1. అ) చదువు మనిషికి మూడో కన్ను. చదువుతో మంచిచెడుల విచక్షణ, ఉద్యోగం, గౌరవం వస్తాయి; మూఢనమ్మకాలు పోతాయి; మోసపోకుండా ఉంటాం. కాబట్టి ప్రతి ఒక్కరూ – ఆడ, మగ తేడా లేకుండా – చదువుకోవాలి అనేది నా అభిప్రాయం ఆ) పరహితుడు అందరికీ మేలు చేస్తాడు కాబట్టి అందరూ అతణ్ణి ప్రేమిస్తారు, ఆదరిస్తారు; అతనికి శత్రువులు ఉండరు; దైవానుగ్రహమూ ఉంటుంది – అందుకే ఎదురులేదు ఇ) మానధనులు (అభిమానవంతులు) మాట తప్పరు – ప్రాణం, ధనం కంటే మాట (సత్యం), గౌరవమే గొప్పవని భావిస్తారు; బలి చక్రవర్తి శుక్రుడు వారించినా వామనుడికి ఇచ్చిన మాట నిలబెట్టుకున్నాడు","2. అ) \"అతిథి దేవో భవ\" – అతిథిని దైవంలా చూడాలని మన సంస్కృతి. ఆకలితో వచ్చిన వారికి ఉన్నంతలో పెట్టడం పుణ్యం; రంతిదేవుడు, శిబి వంటివారు అతిథుల కోసం సర్వం ఇచ్చారు. అతిథి సత్కారం స్నేహం, ప్రేమ పెంచుతుంది; మన గౌరవం పెరుగుతుంది. పోతన \"అతిథులకు పెట్టనివారు కలిగి లేనివారు\" అన్నాడు. కాబట్టి అతిథి సత్కారం మన బాధ్యత ఆ) సమాజానికి మేలు చేసేవారు, సత్యం పలికేవారు, దానం చేసేవారు, అతిథులను సత్కరించేవారు శాశ్వతకీర్తి గలవారు – వారి మంచి పనులు తరతరాలు గుర్తుంటాయి (బలి, కర్ణుడు, గాంధీ, మదర్ థెరిసా)","3. అ) కథ: రాము చదువు మానేసి పశువులు కాసేవాడు. ఒకరోజు ఒక వ్యాపారి అతనితో తప్పు లెక్కలు చెప్పి మోసం చేశాడు. చదువుకున్న మిత్రుడు సీను దాన్ని పట్టుకున్నాడు. రాముకు చదువు విలువ తెలిసింది; రాత్రి బడిలో చేరి చదువుకొని గొప్ప రైతు అయ్యాడు. నీతి: చదువనివాడు అజ్ఞుడు","ఆ) లేఖ: ప్రియమైన మిత్రుడు రవికి, … పరహితమే పరమధర్మం అని పోతన చెప్పాడు. పేద విద్యార్థులకు పుస్తకాలు ఇవ్వడం, వృద్ధులకు సాయం, రక్తదానం, మొక్కలు నాటడం వంటి పనులు చేద్దాం … ఇట్లు, నీ మిత్రుడు","పదజాలం 1. అ) ఆర్య – అయ్య ఆ) ధర్మం – దమ్మం ఇ) కీర్తి – కీరితి","2. చతురత = నేర్పు – రాము చతురతతో సమస్య పరిష్కరించాడు; లేమి = పేదరికం – లేమిలోనూ నిజాయితీ వీడకూడదు; పరహితము = ఇతరుల మేలు – పరహితం కోరేవారు గొప్పవారు; మానధనులు = అభిమానవంతులు – మానధనులు మాట తప్పరు"]],["వ్యాకరణాంశాలు; ప్రాజెక్టు (పుట 7)",["1. అ) ప్రహ్లాదుణ్ణి – నామవాచకం; గురువుల – నామవాచకం; చదవమని – క్రియ ఆ) సన్మానించాలి – క్రియ; సమానులు – విశేషణం ఇ) ఆలోచించు, ఆచరించు – క్రియలు ఈ) ఆహా – అవ్యయం; క్షమ – నామవాచకం; ఎంత – విశేషణం ఉ) మన – సర్వనామం; ముఖ్యం – విశేషణం; పదిమందికి – (సంఖ్యావాచక) నామవాచకం","2. అ) సీత డబ్బును బ్యాంకులో దాచుకుంది ఆ) మంచివారికి మాటే ప్రాణం ఇ) సమయాన్ని మంచి పనుల కొరకు వినియోగించి, మంచిపేరును పొందాలి ఈ) ఆయనకు ఎండవేడి వలన ఇబ్బంది కాబట్టి ఎండలో వెళ్ళరు ఉ) వినయం వలన విద్య ప్రకాశిస్తుంది. సమాజం దాని వలన నిన్ను ఉన్నతుణ్ణి చేస్తుంది","3. అ) రేష్మచేత ప్రార్థన చదువబడింది (కర్మణి) ఆ) నలుడు వంట చేశాడు (కర్తరి) ఇ) నాయకునిచేత శిక్షణ ఇవ్వబడింది (కర్మణి) ఈ) సునీల్ పాఠం చెప్పాడు (కర్తరి)","ప్రాజెక్టు: ఉదా – \"విద్య నిగూఢ గుప్తమగు విత్తము\" (భర్తృహరి), \"సత్యమునకు సాటి ధర్మంబు లేదు\", \"చదువది యెంత గల్గిన\" (సుమతీ), \"ఉప్పుకప్పురంబు\" (వేమన) – సేకరించి సంకలనం చేయాలి"]]]},{"id":"sl2","no":2,"t":"మొద్దబ్బాయిలూ మహామేధావులే","m":[7],"ty":"ఆత్మకథ","th":"ప్రేరణ","by":"తిరుమల రామచంద్ర","sum":"రచయిత కళాశాలలో \"మట్టిబసవడు, రాతిబసవడు, చెక్కబసవడు\" అని ఎగతాళి చేయబడిన మొద్దబ్బాయిలు ఉండేవారు. రాతిబసవడు రామాచార్లు రాత్రంతా చదివినా సంస్కృతంలో మార్కులు రావు. \"బతుకు ముఖ్యం, సంస్కృతం కాదు – ప్రైవేటుగా థర్డ్‌ఫారం ప్యాసై ఉద్యోగం చూసుకో\" అని రచయిత సలహా ఇచ్చాడు. రామాచార్లు ధర్మవరం వెళ్ళి, ఒక ఉపాధ్యాయుడి ఇంటికి చెరువు నుండి మంచినీళ్ళ బిందెలు మోస్తూ, వారాలు చేసుకొని చదివి ఆరవ ఫారం ప్యాసై రైల్వే ఉద్యోగం పొంది స్టేషన్ మాస్టర్ అయ్యాడు; 27 ఏళ్ల తర్వాత రచయితను స్టేషన్‌లో కలిసి కృతజ్ఞత చెప్పాడు. మరో మొద్దు ఏ.వి. సుబ్రహ్మణ్యం సంస్కృత వ్యాసంలో \"ధూమశకటం గిడ్‌గిడ్ ఇతి గచ్ఛతి\" అని పది పుటలు రాసి అవమానపడ్డాడు; రచయిత సలహాతో కాశీ వెళ్ళి మహామహోపాధ్యాయ చిన్నస్వామి శాస్త్రి దగ్గర శిష్యుడై మహావిద్వాంసుడై బెనారస్ విశ్వవిద్యాలయంలో సంస్కృత రీడర్ అయ్యాడు. సరైన సమయంలో చెప్పిన మంచిమాట, పట్టుదల, స్వయంకృషి మొద్దులను మహామేధావులుగా చేస్తాయి.","pts":["రచయిత: డా. తిరుమల రామచంద్ర – అనంతపురం జిల్లా రాఘవంపల్లె; తల్లిదండ్రులు జానకమ్మ, శేషాచార్యులు; కాకినాడ, నెల్లూరు, తిరుపతి, మద్రాసుల్లో చదువు.","రచయిత, విమర్శకుడు, భాషావేత్త, పరిశోధకుడు, పత్రికా రచయిత; జాతీయోద్యమంలో జైలుశిక్ష అనుభవించాడు.","\"హంపీ నుండి హరప్పా దాకా\" (ఆత్మకథ) – కేంద్ర సాహిత్య అకాడమీ పురస్కారం; \"గాథాసప్తశతిలో తెలుగు పదాలు\" – ఆంధ్రప్రదేశ్ సాహిత్య అకాడమీ పురస్కారం.","బిరుదులు: మహామహోపాధ్యాయ, పత్రికారచనా శిరోమణి; తెలుగు విశ్వవిద్యాలయం, అంబేద్కర్ సార్వత్రిక విశ్వవిద్యాలయాల నుండి డాక్టరేట్.","ప్రక్రియ: ఆత్మకథ (స్వీయచరిత్ర) – తమ జీవిత అనుభవాలను తామే గ్రంథస్థం చేయడం; సమకాలిక సంఘటనలూ తెలుస్తాయి.","రాతిబసవడు = రామాచార్లు (స్టేషన్ మాస్టర్); చెక్కబసవడు = ఏ.వి. సుబ్రహ్మణ్యం (సంస్కృత రీడర్, బెనారస్).","\"అదనులో విత్తిన విత్తనంలాగ మంచి సమయంలో ఆడిన మంచిమాట ఫలిస్తుంది\"."],"w":[["మహామూర్ఖులు","చాలా తెలివితక్కువవారు"],["సహాధ్యాయుడు","కలిసి చదువుకున్నవాడు"],["దుర్విధి","దురదృష్టం"],["ఆజానుబాహుడు","మోకాళ్ళ వరకు చేతులున్న పొడగరి"],["చింతాక్రాంతుడు","దిగులుతో ఉన్నవాడు"],["ఇంటిల్లిపాదీ","ఇంట్లో అందరూ"],["ఆచూకీ","జాడ"],["అజ్ఞాతవాసం","ఎవరికీ తెలియకుండా ఉండటం"],["ధూమశకటం","రైలు బండి"],["వారాలు","రోజుకో ఇంట భోజనం"],["కంఠపాఠం","నోటికి రావడం"],["అదను","తగిన సమయం"],["సాగిలపడు","సాష్టాంగ నమస్కారం చేయు"],["దారుశిల్పి","చెక్కపై బొమ్మలు చెక్కేవాడు"],["క్లేశం","కష్టం"]],"gr":{"t":"భాషాంశాలు","p":["త్రిక సంధి: ఆ, ఈ, ఏ లు త్రికం; త్రికం మీది అసంయుక్త హల్లు ద్విత్వమవుతుంది; ద్విత్వానికి ముందున్న త్రికం హ్రస్వమవుతుంది – ఆ + చోట = అచ్చోట, ఈ + కడ = ఇక్కడ, ఏ + విధం = ఎవ్విధం, ఆ + తఱి = అత్తఱి.","ద్వంద్వ సమాసం: రెండూ నామవాచకాలు, రెండింటి అర్థం ప్రధానం – యోగక్షేమాలు, ఆకలిదప్పులు, రాగద్వేషాలు.","ద్విగు సమాసం: మొదటి పదం సంఖ్యావాచకం – పంచపాండవులు, నూరుగురు కుమారులు.","ఉకార సంధి: వారు + ఎవరు = వారెవరు; ఇకార సంధి: చెప్పవలసినది + ఏమి = చెప్పవలసినదేమి; అకార సంధి: చేరిన + అట్లు = చేరినట్లు."]},"qa":[["రాతిబసవడు అసలు పేరు?","రామాచార్లు."],["రచయిత రామాచార్లుకు ఇచ్చిన సలహా?","బతుకు ముఖ్యం, సంస్కృతం కాదు – ప్రైవేటుగా థర్డ్‌ఫారం ప్యాసై, ట్రైనింగ్ చేసి ఉద్యోగం చూసుకో."],["రామాచార్లు ఎలా చదువుకున్నాడు?","ధర్మవరంలో ఉపాధ్యాయుడి ఇంటికి మంచినీళ్ళ బిందెలు మోస్తూ, వారాలు చేసుకుంటూ."],["రామాచార్లు ఏ ఉద్యోగం పొందాడు?","రైల్వే గుమాస్తా → స్టేషన్ మాస్టర్ (తర్వాత డివిజన్ ఇన్‌స్పెక్టర్)."],["సుబ్రహ్మణ్యం ఎవరి దగ్గర చదివాడు?","కాశీలో మహామహోపాధ్యాయ చిన్నస్వామి శాస్త్రి దగ్గర."],["పాఠం సందేశం?","సరైన సమయంలో మంచిమాట, పట్టుదల, స్వయంకృషితో మొద్దులు కూడా మహామేధావులవుతారు."]],"act":"చిన్నప్పుడు సరిగా చదవకపోయినా తర్వాత కష్టపడి పైకి వచ్చిన ప్రముఖుల (ఉదా: థామస్ ఎడిసన్, ఐన్‌స్టీన్) వివరాలు సేకరించి నివేదిక రాసి ప్రదర్శించండి.","kn":"సూక్తి: పరిశ్రమ, తెగువ, ధైర్యం, బుద్ధి, బలం, పరాక్రమం – ఈ ఆరూ ఉన్నచోట దైవం తోడ్పడుతుంది. ఆత్మకథలు: గాంధీ \"సత్యశోధన\", కందుకూరి వీరేశలింగం \"స్వీయచరిత్ర\", అబ్దుల్ కలాం \"అగ్నిసిరగులు\".","qz":[["\"మొద్దబ్బాయిలూ మహామేధావులే\" రచయిత?","తిరుమల రామచంద్ర","కాళ్ళకూరి నారాయణరావు","ఇస్మాయిల్","దేవులపల్లి రామానుజరావు"],["ఈ పాఠం ప్రక్రియ?","ఆత్మకథ","నాటకం","కథానిక","పద్యం"],["పాఠం ఏ గ్రంథం నుండి?","హంపీ నుండి హరప్పా దాకా","గాథాసప్తశతిలో తెలుగు పదాలు","సత్యశోధన","నుడి–నానుడి"],["తిరుమల రామచంద్ర జన్మస్థలం?","రాఘవంపల్లె (అనంతపురం)","బమ్మెర","నెల్లూరు","కాకినాడ"],["రాతిబసవడు అసలు పేరు?","రామాచార్లు","సుబ్రహ్మణ్యం","శంకరనారాయణ","సత్యనారాయణ"],["రామాచార్లు చివరకు ఏ ఉద్యోగం చేశాడు?","రైల్వే స్టేషన్ మాస్టర్","ఉపాధ్యాయుడు","తహసీల్దారు","పోలీసు"],["రామాచార్లు ధర్మవరంలో ఏ పని చేశాడు?","చెరువు నుండి మంచినీళ్ళ బిందెలు మోశాడు","పశువులు కాశాడు","దుకాణం నడిపాడు","టికెట్లు అమ్మాడు"],["\"ధూమశకటం\" అంటే?","రైలు","పొగ","బస్సు","విమానం"],["సుబ్రహ్మణ్యం గురువు?","చిన్నస్వామి శాస్త్రి","శేషాచార్యులు","రామచంద్ర","వడ్లమూడి సత్యనారాయణ"],["సుబ్రహ్మణ్యం చివరకు ఏమయ్యాడు?","బెనారస్ విశ్వవిద్యాలయంలో సంస్కృత రీడర్","స్టేషన్ మాస్టర్","గుమాస్తా","వ్యాపారి"],["రచయితకు జైలుశిక్ష ఎందుకు?","జాతీయోద్యమంలో పాల్గొన్నందుకు","దొంగతనం","పత్రికలో తప్పు","పన్ను కట్టనందుకు"],["\"అదను\" అంటే?","తగిన సమయం","విత్తనం","వర్షం","పొలం"],["ఆ + చోట = ?","అచ్చోట (త్రిక సంధి)","ఆచోట","అచోట","ఆచ్చోట"],["\"పంచపాండవులు\" సమాసం?","ద్విగు","ద్వంద్వ","బహువ్రీహి","షష్ఠీ తత్పురుష"]],"wb":{"mis":"త్రిక సంధిలో రెండు మార్పులు: తర్వాతి హల్లు ద్విత్వం, ముందు దీర్ఘం హ్రస్వం (ఏ + విధం = ఎవ్విధం). \"మీరేమి\", \"రామాజ్ఞ\" త్రిక సంధి కావు.","qz":[["ఏ + విధం = ?","ఎవ్విధం","ఏవిధం","ఎవిధం","ఏవ్విధం"],["త్రిక సంధి పదం ఏది?","అత్తఱి","రామాజ్ఞ","మీరేమి","మేమంతా"],["వారెవరు విడదీస్తే?","వారు + ఎవరు (ఉకార)","వారె + వరు","వా + రెవరు","వారి + ఎవరు"],["సుయోధన + ఆది = ?","సుయోధనాది (సవర్ణదీర్ఘ)","సుయోధనాది (గుణ)","సుయోధనేది","సుయోధనోది"],["\"ఆకలిదప్పులు\" సమాసం?","ద్వంద్వ","ద్విగు","కర్మధారయ","బహువ్రీహి"],["\"దొంగల ___ కోసం పోలీసులు గాలించారు\"","ఆచూకీ","అజ్ఞాతవాసం","ఇంటిల్లిపాదీ","చింతాక్రాంతుడు"]],"pg":"8–17","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":16,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 8)","అవగాహన – ప్రతిస్పందన (పుట 14)","గాంధీ పేరా; పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 15)","పదజాలం; వ్యాకరణాంశాలు (పుట 16)","త్రిక సంధి; ప్రాజెక్టు (పుట 17)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 8)",["1) మహాత్మా గాంధీ 2) ఒకరి జీవితాన్ని వారే రాసుకోవడం (స్వీయచరిత్ర) 3) తన సత్య ప్రయోగాల (సత్యశోధన) అనుభవాలను ఇతరులకు తెలియజేయడానికి 4) గాంధీ – సత్యశోధన; కందుకూరి వీరేశలింగం – స్వీయచరిత్రము; అబ్దుల్ కలాం – అగ్నిసిరగులు (Wings of Fire); నెహ్రూ – నా కథ; తిరుమల రామచంద్ర – హంపీ నుండి హరప్పా దాకా 5) వారి కష్టాలు, పట్టుదల, విలువలు మనకు ప్రేరణనిస్తాయి; జీవితంలో ఎలా ఎదగాలో నేర్పుతాయి; ఆనాటి సమాజం తెలుస్తుంది"]],["అవగాహన – ప్రతిస్పందన (పుట 14)",["1. అ) మొదట చదువులో వెనకబడినవారు తర్వాత గొప్పవారయ్యారని అర్థమైంది ఆ) నిజమే – ప్రతి ఒక్కరిలో ఏదో ప్రతిభ ఉంటుంది; సరైన మార్గదర్శనం, పట్టుదల, సాధన ఉంటే ఎవరైనా గొప్పవారవుతారు (రామాచార్లు, సుబ్రహ్మణ్యం, ఎడిసన్)","2. 1) రాతిబసవని వివరాలు – పేరా 3–4 (పుట 10) 2) రాతిబసవడు కలిసిన వివరాలు – పేరా 6–7 (పుటలు 10–11, యానాద్‌గిరి స్టేషన్) 3) హాస్య సంఘటన – \"ధూమశకటం గిడ్‌గిడ్ ఇతి గచ్ఛతి\" (పుట 12)","3. అ) రచయిత (తిరుమల రామచంద్ర) రామాచార్లుతో ఆ) రామాచార్లు అక్కగారు నర్సమ్మక్క రచయితతో (తన భర్తకు ఉత్తరం రాయమని) ఇ) స్టేషన్ మాస్టర్ రామాచార్లు రచయితతో ఈ) సంస్కృత ఉపాధ్యాయుడు సుబ్రహ్మణ్యంతో"]],["గాంధీ పేరా; పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 15)",["4. అ) సత్యం, అహింస ఆ) ఆలోచనలో, మాటలో, చేతలో సత్యం ఉండాలి; సత్యం లేనిచోట సిసలైన జ్ఞానం ఉండదు ఇ) భగవంతునిలో విశ్వాసం ఉంచడం, భగవంతుని సన్నిధిలో జీవించడం – అంటే సత్యం, అహింసలలో విశ్వాసం ఉండడం ఈ) సత్యం, అహింస, భగవంతునిలో విశ్వాసం","5. అ) \"చూడు రామన్నా! సంస్కృతం రాకపోతే ఏం? నీకు ఇది రాలేదు, మరొకటి ప్రయత్నించు. బతుకు ముఖ్యం, సంస్కృతం కాదు. ప్రైవేటుగా థర్డ్‌ఫారం ప్యాసై, టీచర్స్ ట్రైనింగ్ చేసి జీవితం గడుపు; తర్వాత ఇష్టముంటే చదువు\" ఆ) రామాచార్లు. ధర్మవరంలో ఉపాధ్యాయుడి ఇంటికి మంచినీళ్ళు మోస్తూ, వారాలు చేసుకుంటూ ఆయన శిక్షణతో థర్డ్‌ఫారంలో చేరి, డిక్షనరీ, గ్రామర్ కంఠపాఠం చేసి ఆరవ ఫారం ప్యాసయ్యాడు ఇ) రచయిత సలహాతో కాశీ వెళ్ళి, మహామహోపాధ్యాయ చిన్నస్వామి శాస్త్రి పెట్టిన నెల రోజుల పరీక్షలో నెగ్గి ఆయన దగ్గర చదివి, సంస్కృత కళాశాలలో ఆచార్య పరీక్షల్లో ప్రథముడై మహావిద్వాంసుడయ్యాడు","వ్య.1. అ) సుబ్రహ్మణ్యం అవమానంతో కాశీ వెళ్ళాడు; దారిలో వృద్ధ దంపతులకు సహాయకుడిగా ఉండి చిన్నస్వామి శాస్త్రి ఇంటికి చేరాడు; ఆయన పెట్టిన పరీక్షలో నెగ్గి శ్రద్ధగా చదివి, శాస్త్రాల్లో ప్రథముడై, గ్రంథాలు రాసి బెనారస్ విశ్వవిద్యాలయంలో సంస్కృత రీడర్ అయ్యాడు ఆ) సమర్థిస్తాను – రచయిత సరైన సమయంలో ఇచ్చిన సలహాతోనే రామాచార్లు, సుబ్రహ్మణ్యం జీవితాలు మారాయి; అదనులో విత్తిన విత్తనం పండినట్లే మంచి మాట ఫలిస్తుంది ఇ) శ్రద్ధగా వింటే అవతలివారి బాధ అర్థమవుతుంది, నమ్మకం కలుగుతుంది, సరైన సలహా ఇవ్వగలం, గొడవలు రావు; మనం కూడా నేర్చుకుంటాం","2. అ) తిరుమల రామచంద్ర స్నేహశీలి, ఇతరులను ఎగతాళి చేయని మంచి మనిషి; ఎవరేమి చెప్పినా శ్రద్ధగా వినే స్వభావం; మిత్రులకు సమయానికి మంచి సలహా ఇచ్చి వారి జీవితాలను మార్చాడు; రహస్యాలు దాచే నమ్మకస్తుడు; వ్యాసరచనలో కాలేజీకే మొనగాడు; హాస్యప్రియుడు; భాషావేత్త, పరిశోధకుడు, స్వాతంత్ర్య సమరయోధుడు ఆ) రామాచార్లు: పేదరికంలోనూ నీళ్ళు మోస్తూ, వారాలు చేసుకుంటూ పట్టుదలతో చదివి స్టేషన్ మాస్టర్ అయ్యాడు – శ్రమకు సిగ్గుపడకూడదు; సుబ్రహ్మణ్యం: అవమానాన్ని సవాలుగా తీసుకొని గురువును ఆశ్రయించి మహావిద్వాంసుడయ్యాడు. నేర్చుకోవాల్సినవి – పట్టుదల, స్వయంకృషి, మంచి సలహా పాటించడం, గురుభక్తి, కృతజ్ఞత, నిరాశపడకపోవడం","3. అ) లేఖ/సలహా: \"మిత్రమా, ఒక పరీక్షలో తక్కువ మార్కులు వచ్చాయని నిరుత్సాహపడకు. రామాచార్లు, సుబ్రహ్మణ్యం లాంటి మొద్దబ్బాయిలు పట్టుదలతో మహామేధావులయ్యారు. రోజూ కొంచెం కొంచెం చదువు, సందేహాలు అడుగు, నేను సాయం చేస్తా\" ఆ) వ్యాసం: ప్రతి ఒక్కరికీ ఒక్కో ప్రతిభ ఉంటుంది. సచిన్ చదువులో కాదు, క్రికెట్‌లో; రామాచార్లు సంస్కృతంలో కాదు, రైల్వే ఉద్యోగంలో రాణించారు. ఇష్టమైన రంగాన్ని గుర్తించి కృషి చేస్తే విజయం తథ్యం"]],["పదజాలం; వ్యాకరణాంశాలు (పుట 16)",["1. చింతాక్రాంతుడు – పరీక్ష ఫలితాలు రాక రాము చింతాక్రాంతుడయ్యాడు; ఇంటిల్లిపాదీ – పండక్కి ఇంటిల్లిపాదీ కలిశాం; ఆచూకీ – తప్పిపోయిన పిల్లవాడి ఆచూకీ దొరికింది; అజ్ఞాతవాసం – పాండవులు ఒక సంవత్సరం అజ్ఞాతవాసం చేశారు","2. అ) పట్టాలు ఆ) జాలి (దయ) ఇ) శిరోధార్యాలు ఈ) ఆచూకీ ఉ) స్వయంకృషి","వ్యా.1. అ) చేరినట్లు = చేరిన + అట్లు (అకార సంధి) ఆ) క్లేశాలు + అన్నీ = క్లేశాలన్నీ (ఉకార సంధి) ఇ) సుయోధన + ఆది = సుయోధనాది (సవర్ణదీర్ఘ సంధి) ఈ) వారెవరు = వారు + ఎవరు (ఉకార సంధి) ఉ) చెప్పవలసినదేమి = చెప్పవలసినది + ఏమి (ఇకార సంధి) ఊ) కలిగినప్పుడు = కలిగిన + అప్పుడు (అకార సంధి) ఋ) కృష్ణార్జునులు = కృష్ణ + అర్జునులు (సవర్ణదీర్ఘ సంధి) ౠ) తిడతారు + అని = తిడతారని (ఉకార సంధి)","2. అ) యోగక్షేమాలు – యోగమును, క్షేమమును (ద్వంద్వ) ఆ) పంచపాండవులు – ఐదుగురు పాండవులు (ద్విగు) ఇ) ఆకలిదప్పులు – ఆకలియు, దప్పియు (ద్వంద్వ) ఈ) నూరుగురు కుమారులు – నూరు సంఖ్య గల కుమారులు (ద్విగు) ఉ) రాగద్వేషాలు – రాగమును, ద్వేషమును (ద్వంద్వ)"]],["త్రిక సంధి; ప్రాజెక్టు (పుట 17)",["త్రిక సంధి పదాలు: అత్తఱి = ఆ + తఱి; ఎవ్వారు = ఏ + వారు; ఇత్తఱి = ఈ + తఱి (రామాజ్ఞ – సవర్ణదీర్ఘ, మీరేమి, మేమంతా – ఉకార సంధులు; త్రిక సంధి కాదు)","ప్రాజెక్టు: ఉదా – థామస్ ఆల్వా ఎడిసన్ (బడి నుండి పంపేశారు → గొప్ప శాస్త్రవేత్త), ఆల్బర్ట్ ఐన్‌స్టీన్ (ఆలస్యంగా మాట్లాడాడు → నోబెల్), అబ్దుల్ కలాం (పేపర్లు అమ్మి చదివి → రాష్ట్రపతి) – వివరాలు, నేర్చుకోవాల్సిన విషయాలతో నివేదిక"]]]},{"id":"sl3","no":3,"t":"నవోదయం","m":[7],"ty":"వచన కవిత (గేయ ఛాయ)","th":"చైతన్యం","by":"పల్లా దుర్గయ్య","sum":"తెలుగు వాకిళ్ళలో తొలికోడి కూయగానే తెలుగుకన్నియ తలుపు తెరిచి చూసింది. చిమ్మచీకటి రాత్రి శిథిలమై తూర్పు వాకిట మళ్ళీ సూర్యుడు పొడిచాడు. వేడి వెచ్చని వెలుగు వేయి కిరణాలతో తెలంగాణ మాగాణాలను కౌగిలించింది. కలువ కన్ను మూసింది, కమలం మురిసింది, గాలి ఈలలు వేసి కమ్మగా పాడింది. కన్నెతీగ నాట్యకౌశలం చూపింది, పూలబాలిక తేనెను పుక్కిలించింది. మావిగున్న మదించి సువాసన వెదజల్లింది, గండుకోయిల మధుర గళం విప్పింది. నవోదయం గతదినాల కథలన్నీ చెప్పి, భావికాలంలోని భాగ్యాలను ప్రకటించింది. చీకటి (కష్టాలు) తొలగి కొత్త వెలుగు (చైతన్యం, ఆశ) వస్తుందని కవి సందేశం.","pts":["కవి: పల్లా దుర్గయ్య – వరంగల్ జిల్లా మడికొండ; ఉస్మానియా విశ్వవిద్యాలయం నుండి 1942లో తెలుగులో మొదటి ఎం.ఏ. పట్టా పొందినవారు.","సంస్కృత, ఆంగ్ల, ఆంధ్ర భాషావేత్త, జ్యోతిష్య విశారదుడు; ఉస్మానియాలో అధ్యాపకుడు, ఆచార్యుడిగా 1976లో విరమణ.","రచనలు: ప్రబంధ వాఙ్మయ వికాసము (సిద్ధాంత గ్రంథం), గంగిరెద్దు (కావ్యం), పాలవెల్లి, అల్లసాని పెద్దన, చతురవచోనిధి.","పాఠం \"పాలవెల్లి\" గ్రంథం నుండి. ప్రక్రియ: వచన కవిత – ఛందో నియమాలు ఉండవు.","కవిత్వ లక్షణాలు: భావగాంభీర్యం, అనర్గళ ధార, సద్యఃస్ఫూర్తి, తెలుగు నుడికారం.","నవోదయం = కొత్త ఉదయం; చీకటి = కష్టాలు, వెలుగు = ఆశ, చైతన్యం (ప్రతీకలు)."],"w":[["వాకిలి","గుమ్మం, ద్వారం"],["కన్నియ","కన్య, పెళ్ళికాని అమ్మాయి"],["శిథిలమగు","నశించు, కూలిపోవు"],["కరములు","కిరణాలు; చేతులు"],["మాగాణం","నీటిపారుదల గల పొలం"],["కలువ","రాత్రి వికసించే పువ్వు"],["కమలం","తామర"],["తీవ","తీగ"],["కౌశలం","నేర్పు"],["మధువు","తేనె"],["పుక్కిలించు","నోట నింపి ఊయు"],["మావిగున్న","చిన్న మామిడి చెట్టు"],["తావి","సువాసన"],["గళం","కంఠం"],["భావికాలం","రాబోయే కాలం"]],"gr":{"t":"భాషాంశాలు","p":["అంత్యానుప్రాస అలంకారం: పాదాంతంలో/పదాంతంలో ఒకే విధమైన అక్షరాలు మళ్ళీ మళ్ళీ రావడం – \"పిల్లలం, జల్లులం, మల్లెలం, విల్లులం\"; \"కూసింది – చూసింది\".","పురుషలు: ఉత్తమ పురుష (నేను, మేము), మధ్యమ పురుష (నీవు, మీరు), ప్రథమ పురుష (అతడు, ఆమె, అది, వారు).","వాక్య రకాలు: విధ్యర్థకం (సత్యాన్ని పలకండి), నిషేధార్థకం (చేయవద్దు), అనుమత్యర్థకం (వెళ్ళవచ్చు), సామర్థ్యార్థకం (పాడగలను), ఆశీరర్థకం (చల్లగుండనీ), ప్రార్థనార్థకం (దయచేసి చెప్పండి), హేత్వర్థకం (చదివితేనే…), సందేహార్థకం (చేస్తారో? లేదో?), నిశ్చయార్థకం, ప్రశ్నార్థకం, ఆశ్చర్యార్థకం.","ప్రకృతి–వికృతి: కథ–కత, కన్య–కన్నియ, రాత్రి–రాతిరి."]},"qa":[["తొలికోడి కూయగానే ఏం జరిగింది?","తెలుగుకన్నియ తలుపు తెరిచి చూసింది."],["సూర్యుడి వెలుగు ఏం చేసింది?","వేయి కిరణాలతో తెలంగాణ మాగాణాలను కౌగిలించింది."],["కలువ, కమలం ఎలా స్పందించాయి?","కలువ కన్ను మూసింది (ముడుచుకుంది), కమలం మురిసింది (వికసించింది)."],["గండుకోయిల ఏం చేసింది?","మధుర గళం విప్పి పాడింది."],["నవోదయం ఏం చెప్పింది?","గతదినాల కథలు చెప్పి, భావికాలంలోని భాగ్యాలను ప్రకటించింది."],["కవిత సందేశం?","చీకటి (కష్టాలు) శాశ్వతం కాదు; కొత్త వెలుగు, ఆశ, చైతన్యం వస్తాయి."]],"act":"పాఠశాల గ్రంథాలయం నుండి బాలగేయాలను సేకరించి సంకలనంగా తయారుచేయండి; సూర్యోదయాన్ని చూసి మీ సొంత కవిత రాయండి.","kn":"సూక్తి: జ్ఞానవృద్ధులకు నమస్కరిస్తూ సేవలు చేసేవారికి ఆయుష్షు, విద్య, కీర్తి, బలం వృద్ధి చెందుతాయి.","qz":[["\"నవోదయం\" కవి?","పల్లా దుర్గయ్య","తిరుమల రామచంద్ర","ఇస్మాయిల్","పోతన"],["పాఠం ఏ గ్రంథం నుండి?","పాలవెల్లి","గంగిరెద్దు","అల్లసాని పెద్దన","ప్రబంధ వాఙ్మయ వికాసము"],["ఈ పాఠం ప్రక్రియ?","వచన కవిత","పద్యం","ద్విపద","నాటకం"],["ఉస్మానియాలో తెలుగులో మొదటి ఎం.ఏ. పొందినది?","పల్లా దుర్గయ్య","దేవులపల్లి రామానుజరావు","కాళోజీ","దాశరథి"],["పల్లా దుర్గయ్య స్వగ్రామం?","మడికొండ (వరంగల్)","బమ్మెర","రాఘవంపల్లె","నెల్లూరు"],["తొలికోడి కూయగానే తలుపు తెరిచింది?","తెలుగుకన్నియ","కలువ","కోయిల","గాలి"],["సూర్యోదయంతో కన్నుమూసిన పువ్వు?","కలువ","కమలం","మల్లె","మందారం"],["తేనెను పుక్కిలించింది?","పూలబాలిక","కన్నెతీవ","గండుకోయిల","మావిగున్న"],["తావి గుప్పించినది?","మావిగున్న","కలువ","గాలి","కోయిల"],["\"తావి\" అంటే?","సువాసన","తేనె","తీగ","పాట"],["\"మాగాణం\" అంటే?","నీటి సౌకర్యం గల పొలం","అడవి","కొండ","చెరువు"],["\"కూసింది – చూసింది\" – అలంకారం?","అంత్యానుప్రాస","ఉపమ","రూపకం","అతిశయోక్తి"],["\"దయచేసి చెప్పండి\" – వాక్యం?","ప్రార్థనార్థకం","నిషేధార్థకం","ప్రశ్నార్థకం","ఆశ్చర్యార్థకం"],["రాత్రి – వికృతి?","రాతిరి","రేయి","రాత్తిరి","రాత"]],"wb":{"mis":"\"నేను పాట పాడగలను\" సామర్థ్యార్థకం; \"మీరిక వెళ్ళవచ్చు\" అనుమత్యర్థకం – \"గల\", \"వచ్చు\" లను కలపకండి. నేను/మేము ఉత్తమ పురుష, నీవు/మీరు మధ్యమ పురుష.","qz":[["\"మీరిక వెళ్ళవచ్చు\" – వాక్యం?","అనుమత్యర్థకం","సామర్థ్యార్థకం","విధ్యర్థకం","నిశ్చయార్థకం"],["\"నేను పాట పాడగలను\" – వాక్యం?","సామర్థ్యార్థకం","అనుమత్యర్థకం","ఆశీరర్థకం","హేత్వర్థకం"],["\"మీ కుటుంబం చల్లగుండనీ\" – వాక్యం?","ఆశీరర్థకం","ప్రార్థనార్థకం","నిషేధార్థకం","సందేహార్థకం"],["\"ఇవన్నీ మీరు చేస్తారో? లేదో?\" – వాక్యం?","సందేహార్థకం","ప్రశ్నార్థకం","నిశ్చయార్థకం","విధ్యర్థకం"],["\"నువ్వెప్పుడు వెళ్తావు?\" – ఏ పురుష?","మధ్యమ పురుష","ఉత్తమ పురుష","ప్రథమ పురుష","ఏదీ కాదు"],["\"కౌశలం\" పర్యాయపదాలు?","నేర్పు, నైపుణ్యం","చీకటి, తమస్సు","రోజు, దివసం","చేయి, హస్తం"]],"pg":"18–24","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":26,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 18)","అవగాహన – ప్రతిస్పందన (పుట 21)","పాఠ ప్రశ్న; వ్యక్తీకరణ; పదజాలం (పుట 22)","వ్యాకరణాంశాలు (పుట 23)","అంత్యానుప్రాస; ప్రాజెక్టు (పుట 24)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 18)",["1) తెల్లవారడం (ఉదయం / సూర్యోదయం) గురించి 2) తెల్లవారుజామున మొదటి పొద్దు (సూర్యుడు) పొడవడం 3) కోడి కూసి, చీకటి తొలగగానే తూర్పున ఉదయం పొడసూపుతుంది"]],["అవగాహన – ప్రతిస్పందన (పుట 21)",["1. అ) నవోదయం = కొత్త ఉదయం; కొత్త ఆశలు, కొత్త జీవితం, మార్పు ప్రారంభం – చీకటి పోయి వెలుగు వచ్చినట్లే కష్టాలు పోయి సుఖాలు వస్తాయి కాబట్టి ఆ) సూర్యోదయంతో ప్రకృతి అంతా మేల్కొంటుంది – కలువ ముడుచుకోవడం, తామర వికసించడం, గాలి, తీగలు, పూలు, మామిడి, కోయిల అన్నీ ఆనందిస్తాయి; ఉదయం గతాన్ని గుర్తుచేసి భవిష్యత్తుపై ఆశ కలిగిస్తుంది","2. అ) \"గండుకోయిల మధుర గళము విప్పింది\" ఆ) \"తూర్పువాకిట మరల పొద్దు పొడిచింది\" ఇ) \"పూలబాలిక మధువు పుక్కిలించింది\"","3. అ) i) నార్ల వేంకటేశ్వరరావు; అంత్యప్రాస పదాలు: తొలగునులే–వెలుగునులే, వచ్చునులే–మెచ్చునులే, ఒత్తునులే–ఎత్తునులే, విరియునులే–కురియునులే, నిలుచునులే–పిలుచునులే ii) చీకటి తెర (కష్టాలు) తొలగినప్పుడు iii) రేపు (మంచి కాలం) తప్పక వస్తుంది; అది ఆపదలో ఉన్నవారిని మెచ్చుకొని ఆదుకుంటుంది iv) \"చీకటి తొలగునులే\" / \"నవశకం\" ఆ) కూసింది, చూసింది, పోయింది, పొడిచింది, కౌగిలించింది, మూసింది, మురిసింది, పాడింది, చూపింది, పుక్కిలించింది, గుప్పించింది, విప్పింది, చెప్పింది"]],["పాఠ ప్రశ్న; వ్యక్తీకరణ; పదజాలం (పుట 22)",["4. అ) కోడి కూసింది; తెలుగుకన్నియ తలుపు తెరిచింది; చీకటి నశించి సూర్యుడు పొడిచాడు; వెలుగు మాగాణాలను కౌగిలించింది; కలువ ముడుచుకుంది, కమలం వికసించింది; గాలి పాడింది; తీగలు నాట్యమాడాయి; పూలు తేనెతో నిండాయి; మామిడి సువాసన వెదజల్లింది; కోయిల పాడింది; గతకథలు చెప్పి భవిష్యత్ భాగ్యాలను ప్రకటించింది","వ్య.1. అ) తెలుగు ప్రజల జీవితాల్లో కొత్త మేల్కొలుపు (చైతన్యం) వచ్చిందని, కొత్త రోజు ప్రారంభమైందని గ్రహించాను ఆ) చీకటి (కష్టాలు, బానిసత్వం, అజ్ఞానం) నశించిపోయిందని, ఇక వెలుగు (స్వేచ్ఛ, జ్ఞానం, సుఖం) వచ్చిందని కవి ఉద్దేశం","2. అ) తగినదే. నవోదయం అంటే కొత్త ఉదయం. పాఠమంతా సూర్యోదయ వర్ణనే – కోడికూత, చీకటి నశించడం, సూర్యుడి కిరణాలు, కలువ, కమలం, గాలి, తీగ, పూలు, మామిడి, కోయిల. అంతేకాక కొత్త కాలం, కొత్త ఆశలు, భావి భాగ్యాలను కవి చెప్పాడు. కాబట్టి \"నవోదయం\" శీర్షిక భావానికి, వర్ణనకు రెండిటికీ సరిపోతుంది","3. అ) కవిత: \"తూరుపు కొండల తొంగిచూసె / ఎర్రని సూరీడు నవ్వుతూ / పక్షులు పాడెను పాటలు / పూవులు విరిసెను తోటలో / చీకటి పారెను దూరముగా / వెలుగులు నిండెను లోకమున\"","పదజాలం 1. అ) శిథిలమైపోవడం = నశించడం – పాత గుడి శిథిలమైపోయింది ఆ) మాగాణం = నీటి వసతి గల పొలం – మాగాణంలో వరి పండుతుంది ఇ) నాట్యకౌశలం = నృత్యంలో నేర్పు – సీత నాట్యకౌశలం అందరినీ మెప్పించింది ఈ) మధురగళం = తీయని కంఠం – ఆమె మధురగళంతో పాడింది ఉ) భావికాలం = రాబోయే కాలం – భావికాలంలో మంచి రోజులు వస్తాయి","2. అ) కరం = చేయి, హస్తం (కిరణం) ఆ) కౌశలం = నేర్పు, నైపుణ్యం ఇ) దినం = రోజు, దివసం ఈ) చీకటి = అంధకారం, తమస్సు","3. ప్రకృతి – వికృతి: కథ – కత; కన్య – కన్నియ; రాత్రి – రాతిరి"]],["వ్యాకరణాంశాలు (పుట 23)",["1. ఉత్తమ పురుష: వెళ్ళాను; చదవలేదన్నాను; మిత్రుడు నరసింహతో కలిసి చర్చిస్తాను; నీకు కూరగాయలు తీసుకొచ్చి ఇచ్చి వెళ్తానమ్మా","మధ్యమ పురుష: \"నవోదయం పాఠం చదివావా?\"; ఐతే మరి నువ్వెప్పుడు వెళ్తావు?; సరే, బాగా చదువు; బట్టీ పట్టకు; అర్థంచేసుకొని అవగాహనతో చదువుకో","ప్రథమ పురుష: మా అమ్మ నన్ను పిలిచింది; వాడికి అన్ని పదాల అర్థాలు తెలుసు; వాళ్ళ అక్కయ్యనడిగి తెలుసుకొన్నాడట","2. అ) ప్రార్థనార్థకం ఆ) అనుమత్యర్థకం ఇ) నిషేధార్థకం ఈ) ప్రశ్నార్థకం ఉ) ఆశ్చర్యార్థకం ఊ) ఆశీరర్థకం ఋ) సందేహార్థకం ౠ) హేత్వర్థకం ఎ) సామర్థ్యార్థకం ఏ) నిశ్చయార్థకం ఐ) విధ్యర్థకం"]],["అంత్యానుప్రాస; ప్రాజెక్టు (పుట 24)",["అంత్యానుప్రాస అలంకారం: కురవాలి, నిండాలి, పండాలి, నడవాలి – ప్రతి పాదం చివర \"ఆలి\" అనే ఒకే విధమైన అక్షరాలు మళ్ళీ మళ్ళీ వచ్చాయి కాబట్టి","ప్రాజెక్టు: బాలగేయాలు (ఉదా: \"చందమామ రావే జాబిల్లి రావే\", \"బుజ్జి మేక బుజ్జి మేక\", \"ఏనుగమ్మ ఏనుగు\") సేకరించి సంకలనం చేయాలి"]]]},{"id":"sl4","no":4,"t":"సంజయ రాయబారం","m":[8],"ty":"ఇతిహాస కథ","th":"మానవస్వభావం","by":"ఉషశ్రీ","sum":"అజ్ఞాతవాసం పూర్తయ్యాక పాండవులు తమ రాజ్యభాగం కోసం ద్రుపదుని పురోహితుణ్ణి హస్తినకు రాయబారిగా పంపారు. దానికి ప్రతిగా ధృతరాష్ట్రుడు సంజయుణ్ణి ఉపప్లావ్యానికి పంపాడు. పాండవులు సాధుస్వభావులు, ధర్మం తప్పనివారు; అర్జునుడు, కృష్ణుడు, భీముడు, నకుల సహదేవులు ఉన్న వారితో వైరం పెంచుకుంటున్నాడు మందబుద్ధి దుర్యోధనుడు – \"నేను శాంతినే కోరుతున్నాను అని గట్టిగా చెప్పు, క్రోధాన్ని దరిజేరనివ్వకు\" అని ధృతరాష్ట్రుడు చెప్పాడు. ధర్మరాజు సంజయుణ్ణి ఆదరించి భీష్మ, ద్రోణ, కృప, అశ్వత్థామ, కర్ణ, కౌరవుల క్షేమం అడిగాడు. సంజయుడు \"యుద్ధం సర్వనాశనం; శాంతే శ్రేయస్కరం; రాజ్యం ఇవ్వకపోయినా యుద్ధం కంటే అరణ్యవాసమే మేలు\" అన్నాడు. ధర్మరాజు \"యుద్ధం లేకుండా పని జరిగితే అంతకంటే కావలసింది లేదు; కానీ లోభి దుర్యోధనుడు రాజ్యం ఇవ్వడు. మా ఇంద్రప్రస్థం మాకిస్తే అందరం సుఖంగా ఉంటాం. ధర్మం సూక్ష్మం – ఆపద్ధర్మమూ ఉంది; నేను తాతతండ్రుల ధర్మమార్గం విడవను; వాసుదేవుని మాటను పాటిస్తాం\" అని జవాబిచ్చాడు.","pts":["రచయిత: ఉషశ్రీ (1928–1990) – అసలు పేరు పురాణపండ సూర్యప్రకాశ దీక్షితులు; తూర్పుగోదావరి జిల్లా ఆలమూరు.","ఆకాశవాణిలో ధారావాహికంగా ప్రసారమైన \"ఉషశ్రీ భారతం\" అశేష ఆదరణ పొందింది; రామాయణ, భారత, భాగవతాలను వచనంలో రాశారు; ప్రవచనాలు చేశారు.","పాఠం ఉషశ్రీ భారతం (మొదటి భాగం) ఉద్యోగ పర్వం నుండి. ప్రక్రియ: ఇతిహాస కథ (రామాయణ, భారతాలు ఇతిహాసాలు).","రాయబారం = రెండు పక్షాల మధ్య సంధి కోసం ఒకరి సందేశాన్ని మరొకరికి చేర్చడం; పాండవుల రాయబారి ద్రుపద పురోహితుడు, కౌరవుల రాయబారి సంజయుడు.","పాండవులు ఉన్న చోటు: ఉపప్లావ్యం (విరాట రాజ్యం). ధర్మరాజు అజాతశత్రువు.","ఆపద్ధర్మం: జీవితం నడవడం కష్టమైనప్పుడు సత్కర్మకు లోపం రాకుండా చేసే పని – దోషం కాదు.","నన్నయ: \"మహాభారతం ఆర్ష విజ్ఞాన సర్వస్వం – ధర్మశాస్త్రం, వేదాంతశాస్త్రం, సాహితీ భాండాగారం, ఇతిహాసం, నీతిశాస్త్రం\"."],"w":[["రాయబారం","దౌత్యం"],["క్లేశం","కష్టం, బాధ"],["అజాతశత్రువు","శత్రువులే లేనివాడు"],["సవ్యసాచి","రెండు చేతులతో బాణాలు వేయగలవాడు (అర్జునుడు)"],["గాండీవం","అర్జునుని ధనుస్సు"],["ధనుష్టంకారం","వింటినారి ధ్వని"],["వైరం","శత్రుత్వం"],["ఉద్దండ","భయంకరమైన"],["ప్రాజ్ఞుడు","తెలివైనవాడు"],["భోగతృష్ణ","సుఖాలపై ఆశ"],["పరుషభాషణం","కఠినంగా మాట్లాడటం"],["శిరోవేదన","తలనొప్పి"],["వానప్రస్థం","అడవిలో జీవించే ఆశ్రమం"],["ఆరితేరు","నేర్పు సాధించు"],["లోభబుద్ధి","పిసినారితనం, ఆశబోతుతనం"]],"gr":{"t":"భాషాంశాలు","p":["యణాదేశ సంధి: ఇ, ఉ, ఋ లకు భిన్నమైన అచ్చులు పరమైతే క్రమంగా య, వ, ర లు ఆదేశం – అతి + అద్భుతం = అత్యద్భుతం; అణు + ఆయుధం = అణ్వాయుధం; మాతృ + ఆజ్ఞ = మాత్రాజ్ఞ; పితృ + ఆజ్ఞ = పిత్రాజ్ఞ; మధు + అరి = మధ్వరి.","యణ్ణులు: య, వ, ర.","పురుషవాచకం (మహద్వాచకం – పురుషులు): అతడు రానే వచ్చాడు. స్త్రీవాచకం: అమ్మ అతని వెంట వచ్చింది.","వ్యతిరేక పదాలు: శాశ్వతం×అశాశ్వతం, అపకీర్తి×కీర్తి, పుణ్యకర్మ×పాపకర్మ, అనుచితం×ఉచితం, అసత్యం×సత్యం, అపజయం×జయం."]},"qa":[["సంజయుణ్ణి రాయబారిగా ఎవరు, ఎక్కడికి పంపారు?","ధృతరాష్ట్రుడు, పాండవులు ఉన్న ఉపప్లావ్యానికి."],["ధృతరాష్ట్రుడు సంజయునికి ఇచ్చిన ముఖ్య సూచన?","నేను శాంతినే కోరుతున్నానని గట్టిగా చెప్పు; ఏ దశలోనూ క్రోధాన్ని దరిజేరనివ్వకు."],["ధర్మరాజు ఎవరెవరి క్షేమం అడిగాడు?","భీష్ముడు, ధృతరాష్ట్ర నందనులు, కర్ణుడు, వృద్ధ స్త్రీలు, కృప, ద్రోణ, అశ్వత్థామ, మంత్రులు, పరిజనులు."],["సంజయుడు యుద్ధం గురించి ఏమన్నాడు?","యుద్ధం పాపకర్మ, సర్వనాశనం; రాజ్యం ఇవ్వకపోయినా యుద్ధం కంటే అరణ్యాల్లో ఉండటమే మేలు."],["ధర్మరాజు కోరిక?","ఇంద్రప్రస్థం (తమ రాజ్యభాగం) తమకు ఇస్తే అందరూ సుఖశాంతులతో ఉంటారు."],["ఆపద్ధర్మం అంటే?","జీవితం కష్టమైనప్పుడు సత్కర్మకు లోపం లేకుండా చేసే పని."]],"act":"\"సంజయ రాయబారం\" పాఠాన్ని ధృతరాష్ట్రుడు, సంజయుడు, ధర్మరాజు పాత్రలతో నాటకీకరణ చేయండి; పిల్లల మహాభారతం చదివి నచ్చిన పాత్రపై నివేదిక రాయండి.","kn":"సూక్తి (నన్నయ): మహాభారతం ఆర్ష విజ్ఞాన సర్వస్వం – ధర్మతత్త్వజ్ఞులకు ధర్మశాస్త్రం, ఆధ్యాత్మికవేత్తలకు వేదాంతశాస్త్రం, కవులకు సాహితీ భాండాగారం, ఐతిహాసికులకు ఇతిహాసం, నీతికోవిదులకు నీతిశాస్త్రం.","qz":[["\"సంజయ రాయబారం\" రచయిత?","ఉషశ్రీ","తిరుమల రామచంద్ర","పోతన","కాళ్ళకూరి నారాయణరావు"],["ఉషశ్రీ అసలు పేరు?","పురాణపండ సూర్యప్రకాశ దీక్షితులు","తిరుమల రామచంద్ర","పల్లా దుర్గయ్య","దేవులపల్లి రామానుజరావు"],["ఉషశ్రీ భారతం ఎక్కడ ధారావాహికంగా ప్రసారమైంది?","ఆకాశవాణి","దూరదర్శన్","పత్రిక","సినిమా"],["పాఠం భారతంలోని ఏ పర్వం?","ఉద్యోగ పర్వం","విరాట పర్వం","సభా పర్వం","భీష్మ పర్వం"],["సంజయుణ్ణి రాయబారిగా పంపినది?","ధృతరాష్ట్రుడు","దుర్యోధనుడు","భీష్ముడు","విదురుడు"],["పాండవులు ఉన్న చోటు?","ఉపప్లావ్యం","హస్తినాపురం","ఇంద్రప్రస్థం","ద్వారక"],["పాండవుల తరఫున హస్తినకు వెళ్ళిన రాయబారి?","ద్రుపదుని పురోహితుడు","సంజయుడు","విదురుడు","భీముడు"],["\"సవ్యసాచి\" ఎవరు?","అర్జునుడు","భీముడు","కర్ణుడు","కృష్ణుడు"],["\"అజాతశత్రువు\" ఎవరు?","ధర్మరాజు","దుర్యోధనుడు","శకుని","కర్ణుడు"],["ధర్మరాజు కోరిన రాజ్యం?","ఇంద్రప్రస్థం","హస్తినాపురం","ఉపప్లావ్యం","మధుర"],["\"నెయ్యి పడేకొద్దీ అగ్ని ప్రజ్వలిస్తుంది\" – దేనికి పోలిక?","సుఖాలపై వ్యామోహం","యుద్ధం","కోపం","ధర్మం"],["సంజయుని ప్రకారం కోపం వల్ల?","తీపి చేదుగా ఉంటుంది, తలనొప్పి, కీర్తి నాశనం","ధనం వస్తుంది","బలం పెరుగుతుంది","సుఖం కలుగుతుంది"],["అతి + ఆశ = ?","అత్యాశ (యణాదేశ సంధి)","అతాశ","అతీశ","అతియాశ"],["యణ్ణులు ఏవి?","య, వ, ర","అ, ఇ, ఉ","క, చ, ట","ఆ, ఈ, ఏ"]],"wb":{"mis":"యణాదేశంలో ఇ→య, ఉ→వ, ఋ→ర; ఒకే అచ్చు (సవర్ణం) పరమైతే సవర్ణదీర్ఘం అవుతుంది, యణాదేశం కాదు (దేవాలయం = సవర్ణదీర్ఘం).","qz":[["యణాదేశ సంధి పదం?","పిత్రాజ్ఞ","దేవాలయం","అమ్మమ్మ","నీవేమి"],["మధ్వరి విడదీస్తే?","మధు + అరి","మధ్వ + అరి","మధ + వరి","మధూ + అరి"],["అణు + ఆయుధం = ?","అణ్వాయుధం","అణాయుధం","అణూయుధం","అణువాయుధం"],["ఇత్యాదులు విడదీస్తే?","ఇతి + ఆదులు","ఇత్య + ఆదులు","ఇతి + యాదులు","ఇత + ఆదులు"],["\"శాశ్వతం\" వ్యతిరేక పదం?","అశాశ్వతం","నిత్యం","స్థిరం","చిరకాలం"],["\"అమ్మ గంగమ్మకు పూజ చేసింది\" – ఏ వాచకం?","స్త్రీవాచకం","పురుషవాచకం","నపుంసకవాచకం","ఏదీ కాదు"]],"pg":"25–36","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":33,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 25)","అవగాహన – ప్రతిస్పందన (పుట 33)","పేరా ప్రశ్నలు; పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 34)","వ్యక్తీకరణ (వ్యాస, సృజనాత్మక); పదజాలం; వ్యాకరణం (పుట 35)","యణాదేశ సంధి; ప్రాజెక్టు (పుట 36)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 25)",["1) శ్రీకృష్ణుడు ద్రుపదుని (సభలోని పెద్దలను) ఉద్దేశించి చెప్పాడు 2) అజ్ఞాతవాసం తర్వాత విరాటుని కొలువులో (ఉపప్లావ్యంలో) పాండవుల రాజ్యం గురించి కౌరవుల దగ్గరకు దూతను పంపాలని ఆలోచిస్తున్న సందర్భం 3) రాయబారం = ఇరుపక్షాల మధ్య సంధి కోసం ఒకరి సందేశాన్ని మరొకరికి తెలియజేయడం (దౌత్యం) 4) సౌమ్యంగా, మర్యాదగా, నిర్భయంగా, ఇరుపక్షాలకూ మేలు కలిగేలా, కోపం లేకుండా, సత్యం పలుకుతూ, సమయస్ఫూర్తితో మాట్లాడాలి"]],["అవగాహన – ప్రతిస్పందన (పుట 33)",["1. అ) యుద్ధం పనికిరాదు – ప్రాణనష్టం, ఆస్తినష్టం, అనాథలు, ద్వేషం పెరుగుతాయి; చర్చలతో సమస్యలు పరిష్కరించుకోవచ్చు (లేదా) ఆ) అన్ని శాంతి మార్గాలు విఫలమై, ధర్మాన్ని, దేశాన్ని కాపాడుకోవడానికి తప్పనిసరైనప్పుడు యుద్ధం చేయవచ్చు","2. ధర్మరాజు – అజాతశత్రువు, ధర్మపరాయణుడు, శాంతిప్రియుడు, క్షమాశీలి, సత్యవాది, వినయశీలి","భీష్ముడు – ధర్మాధర్మకోవిదుడు, శాంతి కోరేవాడు, పాండవులపై ఆదరం గలవాడు","విదురుడు – విద్వాంసుడు, హితబోధకుడు, ధర్మాత్ముడు","ధృతరాష్ట్రుడు – పుత్రవ్యామోహి, లోభబుద్ధి, పాండవుల బలం తెలిసినా కొడుకును విడువలేనివాడు, శాంతి కోరినట్లు నటించేవాడు","దుర్యోధనుడు – మందబుద్ధి, రాగద్వేషాలకు లొంగినవాడు, అసూయ, క్రోధం, లోభం, పరుషభాషణం, మిత్రద్రోహం గలవాడు","3. అ) ధృతరాష్ట్రుడు సంజయునితో – పాండవుల క్షేమం తెలుసుకోవడానికి రాయబారిగా పంపే సందర్భం ఆ) ధర్మరాజు సంజయునితో – సంజయుడు ఉపప్లావ్యం చేరి కుశలం చెప్పినప్పుడు ఇ) సంజయుడు ధర్మరాజుతో – ధృతరాష్ట్రుని సందేశం సభలో వినిపించే ముందు ఈ) ధర్మరాజు సంజయునితో – సుఖభోగాల మీద వ్యామోహం పెరుగుతుందని, దుర్యోధనుడి భోగతృష్ణను వివరించే సందర్భం"]],["పేరా ప్రశ్నలు; పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 34)",["4. అ) సంజయ రాయబార సందర్భంలో శ్రీకృష్ణుడు సంజయునితో అన్న మాటలు; పాండవుల (ధర్మరాజు) పక్షాన మాట్లాడాడు ఆ) శాంతంగా తమ రాజ్యం తమకు లభించాలని – తాతతండ్రులు నేర్పిన క్షాత్రధర్మం పాటించడం కోసం ఇ) ప్రభువు ముందుగా ధర్మవర్తనుడు కావాలి; ధర్మవ్రతులనే న్యాయాధిపతులుగా నియమించాలి; క్రూరులను దండించాలి ఈ) ధర్మం ప్రకారం నడుచుకొనేవాడు ఉ) అవుతుంది – ధర్మాన్ని, ప్రజలను కాపాడడానికి, క్రూరులను దండించడానికి చేసే యుద్ధం క్షత్రియ ధర్మం; శత్రువుకు భయపడి పారిపోవడం వీరధర్మం కాదు","5. అ) పాండవులు సాధుస్వభావులు, పరోపకారులు; మోసం ఎరుగరు; ధర్మవిరుద్ధంగా ప్రవర్తించరు; స్నేహబంధం కాపాడుకుంటారు; అర్జునుడు, కృష్ణుడు, భీముడు, నకుల సహదేవులు మహావీరులు – వారితో వైరం మంచిది కాదు ఆ) ధర్మరాజును ముందుగా దర్శించాలి; ఆదర వచనాలతో అందరి యోగక్షేమాలు అడగాలి; \"నేను శాంతినే కోరుతున్నాను\" అని గట్టిగా చెప్పాలి; ఏ దశలోనూ క్రోధాన్ని దరిజేరనివ్వకూడదు ఇ) ధృతరాష్ట్రుడు, భీష్ముడు, ధృతరాష్ట్ర నందనులు, కర్ణుడు, కుటుంబ వృద్ధ స్త్రీలు, కృపాచార్యుడు, ద్రోణాచార్యుడు, అశ్వత్థామ, దుర్యోధనుని మంత్రులు, పరిజనులు ఈ) యుద్ధం చేయకుండా పని జరిగితే అంతకంటే కావలసింది లేదు; ధర్మంగా వచ్చినవే స్వీకరిస్తాం; యుద్ధంలో విజయం పుణ్యాత్ములకే; రాజ్యం ఇవ్వకపోతే మరో మార్గాన సాధించుకోగలం ఉ) యుద్ధం సర్వనాశనానికి దారితీసే పాపకర్మ; జయాపజయాలు ముందుగా చెప్పలేం; భీష్మ, ద్రోణాదుల సంహారం మీకు సంతోషమా? రాజ్యలోభంతో యుద్ధం కంటే అరణ్యవాసమే మేలు","వ్య.1. అ) రాయబారం = రెండు పక్షాల మధ్య సంధి కోసం సందేశం చేరవేయడం. లక్షణాలు: వాక్చాతుర్యం, సమయస్ఫూర్తి, ఓర్పు, నిర్భయత్వం, నిష్పక్షపాతం, కోపం లేకపోవడం, ఇరుపక్షాల శ్రేయస్సు కోరడం, మర్యాద ఆ) ధర్మం = న్యాయమైన, సత్యమైన మార్గం (కర్తవ్యం). ఆపద్ధర్మం = ఆపద సమయంలో సత్కర్మకు లోపం లేకుండా చేసే పని. ధర్మమే శాశ్వతం, అది రక్షించేవారిని రక్షిస్తుంది; కీర్తి ధర్మం వల్లే వస్తుంది కాబట్టి ధర్మం శ్రేష్ఠమని ధర్మరాజు అన్నాడు ఇ) సమర్థిస్తాను – ఆపదలో బతకడం కోసం ఇతరులకు హాని లేకుండా చేసే ఏ పనీ తప్పు కాదు (పాండవులు అజ్ఞాతవాసంలో వేషాలు మార్చుకుని సేవకులుగా ఉన్నారు); కానీ ఎల్లప్పుడూ ఆపద్ధర్మమే పాటించకూడదు ఈ) కోపం మనిషికి శత్రువు; ఆరోగ్యం, ఆనందం, కీర్తిని నాశనం చేస్తుంది; కోపాన్ని జయించి శాంతంగా ఉండాలి"]],["వ్యక్తీకరణ (వ్యాస, సృజనాత్మక); పదజాలం; వ్యాకరణం (పుట 35)",["2. అ) పాండవులు: ధర్మపరులు, సత్యవంతులు, శాంతిప్రియులు, క్షమాశీలురు, వీరులు, మిత్రులను కాపాడుకునేవారు, పెద్దలను గౌరవించేవారు – అవమానాలు భరించినా సోదరదృష్టితో చూశారు. కౌరవులు: దుర్యోధనుడు లోభి, అసూయాపరుడు, మందబుద్ధి, మోసంతో జూదంలో పాండవుల సంపద హరించాడు; ధృతరాష్ట్రుడు పుత్రవ్యామోహంతో ధర్మం విడిచాడు; విదురుని హితబోధ వినలేదు ఆ) కారణాలు: దుర్యోధనుని అసూయ, రాజ్యకాంక్ష, లోభం; మోసపూరిత జూదం; ద్రౌపదీ పరాభవం; ధృతరాష్ట్రుని పుత్రవ్యామోహం; ఒప్పందం ప్రకారం రాజ్యం తిరిగి ఇవ్వకపోవడం; కర్ణ, శకునుల దుర్బోధ; పెద్దల హితవు వినకపోవడం","3. అ) సంభాషణ: ధృతరాష్ట్రుడు: \"సంజయా! ఉపప్లావ్యం వెళ్ళి పాండవుల క్షేమం తెలుసుకో; నేను శాంతి కోరుతున్నానని చెప్పు.\" సంజయుడు: \"అలాగే మహారాజా!\" … ధర్మరాజు: \"సంజయా! నీ రాక సంతోషం. పెద్దలందరూ క్షేమమా?\" సంజయుడు: \"అందరూ కుశలమే. మా మహారాజు శాంతినే కోరుతున్నాడు.\" ధర్మరాజు: \"మా ఇంద్రప్రస్థం మాకిస్తే అందరం సుఖంగా ఉంటాం.\" (ప్రదర్శించాలి) ఆ) లేఖ: \"సంపాదకులకు, … యుద్ధాల వల్ల లక్షల ప్రాణాలు పోతాయి, పిల్లలు అనాథలవుతారు, దేశాల ఆర్థిక వ్యవస్థ కుప్పకూలుతుంది, ప్రకృతి నాశనమవుతుంది. చర్చల ద్వారానే సమస్యలు పరిష్కరించుకోవాలి. శాంతే అభివృద్ధికి మూలం. ఇట్లు, …\"","పదజాలం 1. అ) శాశ్వతం × అశాశ్వతం – జీవితం అశాశ్వతం ఆ) అపకీర్తి × కీర్తి – మంచి పనులతో కీర్తి వస్తుంది ఇ) పుణ్యకర్మలు × పాపకర్మలు – పాపకర్మలు చేయకూడదు ఈ) అనుచితం × ఉచితం – పెద్దలను గౌరవించడం ఉచితం ఉ) అసత్యం × సత్యం – సత్యమే పలకాలి ఊ) అపజయం × జయం – కృషితో జయం తథ్యం","2. అ) రాగద్వేషాలు – రాగద్వేషాలు వదిలి న్యాయం చెప్పాలి ఆ) ఘనకార్యం – చెరువు బాగుచేయడం గ్రామస్థులు చేసిన ఘనకార్యం ఇ) ఆరితేరారు – అర్జునుడు విలువిద్యలో ఆరితేరాడు ఈ) జయాపజయాలు – ఆటలో జయాపజయాలు సహజం ఉ) హితబోధలు – పెద్దల హితబోధలు వినాలి ఊ) లోభబుద్ధి – లోభబుద్ధి గలవారికి సుఖం ఉండదు","వ్యా.1. పురుషవాచకం: అతడు రానే వచ్చాడు; అతను నాకు మంచి మిత్రుడు; (నా మిత్రుడు నేను కలిసి గంగకు హారతినిచ్చాం)","స్త్రీవాచకం: అమ్మ కూడా అతని వెంట వచ్చింది; గంగానది ప్రశాంతంగా ప్రవహిస్తోంది; అమ్మ గంగమ్మకు పూజ చేసింది; స్త్రీలందరూ దీపాలు వెలిగించి నీళ్ళల్లో వదిలిపెడుతున్నారు"]],["యణాదేశ సంధి; ప్రాజెక్టు (పుట 36)",["యణాదేశ సంధి పదాలు: ఇత్యాదులు = ఇతి + ఆదులు; పిత్రాజ్ఞ = పితృ + ఆజ్ఞ; మధ్వరి = మధు + అరి; అత్యాశ = అతి + ఆశ (దేవాలయం – సవర్ణదీర్ఘ; ఇవ్వేళ, నీవేమి, అమ్మమ్మ – ఇతర సంధులు)","ప్రాజెక్టు: అ) పిల్లల మహాభారతం చదివి నచ్చిన పాత్ర (ఉదా: కర్ణుడు – దానశీలి, స్నేహానికి ప్రాణమిచ్చినవాడు; భీష్ముడు – ప్రతిజ్ఞాపాలకుడు) పై నివేదిక ఆ) \"సంజయ రాయబారం\" నాటకీకరణ"]]]},{"id":"sl5","no":5,"t":"కల్యాణం","m":[8],"ty":"ద్విపద","th":"సంస్కృతి","by":"తరిగొండ వెంగమాంబ","sum":"శ్రీ వేంకటేశ్వరస్వామి (హరి), లక్ష్మీదేవి (రమ) కల్యాణ వర్ణన ఇది. పార్వతి, సరస్వతి మొదలైనవారు ముత్తైదువులుగా రాగా కశ్యపుడు వివాహ కార్యక్రమాలు జరిపించాడు. మంగళస్నానం, పుణ్యాహవాచనం, స్నాతకం, వ్రతాలు చేసిన తర్వాత హరి కాశీయాత్రకు బయలుదేరగా, సముద్రుడు (లక్ష్మి తండ్రి) \"కపటనాటకా! కాశీకి ఎందుకు? నా కూతురిని నీకిస్తాను\" అని ప్రార్థించి మందిరానికి తీసుకెళ్ళాడు. మునులు కన్యావరణం జరిపారు. సముద్రుడు మధుపర్కం, కొత్త నగలు, వస్త్రాలు, గంధం, పూలమాలలు ఇచ్చి భార్యతో కలిసి కన్యాదానం చేశాడు. హరి రమ చేయి పట్టి (పాణిగ్రహణం) శంఖం వంటి కంఠంలో మంగళసూత్రం కట్టాడు. ఇద్దరూ ఒకరి తలపై ఒకరు తలంబ్రాలు పోసుకున్నారు. తర్వాత నక్షత్ర దర్శనం (అరుంధతీ), లాజహోమం మొదలైనవి సంప్రదాయబద్ధంగా జరిగాయి.","pts":["కవయిత్రి: తరిగొండ వెంగమాంబ (1730–1817) – తిరుపతికి సుమారు 100 కి.మీ. దూరంలోని తరిగొండ గ్రామం.","సంప్రదాయ కుటుంబంలో పుట్టి సాంఘిక దురాచారాలపై తిరుగుబాటు చేసింది; వేంకటేశ్వరుని పరమభక్తురాలు – జీవితమంతా స్వామి సన్నిధిలో గడిపింది.","రచనలు: శ్రీ వేంకటాచల మాహాత్మ్యం, తరిగొండ నృసింహ శతకం, రమాపరిణయం, ద్విపద భాగవతం, చెంచునాటకం (యక్షగానం) మొదలైనవి.","పాఠం \"రమాపరిణయం\" లోని శ్రీ వేంకటేశ్వర కల్యాణ ఘట్టం. ప్రక్రియ: ద్విపద – రెండు పాదాలు; పాడుకోవడానికి వీలు; ప్రాస నియమం ఉంటుంది; ప్రాస నియమం లేనిది \"మంజరీ ద్విపద\".","వివాహ ఘట్టాలు: మంగళస్నానం, పుణ్యాహవాచనం, స్నాతకం, కాశీయాత్ర, కన్యావరణం, మధుపర్కం, కన్యాదానం, పాణిగ్రహణం, మంగళసూత్రధారణ, తలంబ్రాలు, నక్షత్ర (అరుంధతీ) దర్శనం, లాజహోమం.","లాజహోమం = పేలాలతో వధువు చేత వేయించే హోమం."],"w":[["ముత్తైదువ","భర్త జీవించి ఉన్న స్త్రీ, సుమంగళి"],["తోయధి","సముద్రం"],["సుత","కూతురు"],["మగుడి","మళ్ళీ, తిరిగి"],["పంకజాక్షుడు","తామరరేకుల కన్నులవాడు (విష్ణువు)"],["మధుపర్కం","వరుడికి ఇచ్చే పెరుగు–తేనె మిశ్రమం (కానుక)"],["మాల్యం","పూలమాల"],["కరగ్రహణం","పాణిగ్రహణం, చేయి పట్టడం"],["దరనిభకంఠం","శంఖం వంటి కంఠం"],["సురుచిర","మిక్కిలి అందమైన"],["జలరాశి కన్య","సముద్రుని కూతురు – లక్ష్మి"],["లాజలు","పేలాలు"],["వేడ్క","సంతోషం"],["ఆభరణాలు","నగలు"],["ప్రాలు","బియ్యం"]],"gr":{"t":"భాషాంశాలు","p":["గుణ సంధి: అకారానికి ఇ, ఉ, ఋ లు పరమైతే ఏ, ఓ, అర్ లు ఏకాదేశం – సకల + ఉత్సవములు = సకలోత్సవములు; మహా + ఇంద్రుడు = మహేంద్రుడు; మహా + ఋషి = మహర్షి.","త్రిక సంధి: ఈ + చోట = ఇచ్చోట; ఏ + వారు = ఎవ్వారు; ఆ + గజేంద్రము = అగ్గజేంద్రము.","వృత్త్యనుప్రాస అలంకారం: ఒకే హల్లు అనేకసార్లు రావడం – \"నల్ల పిల్లి మెల్లగా బల్లకిందికి వెళ్ళి చల్లని చల్ల తాగింది\".","ఛందస్సు – గణాలు: లగం (IU), గలం (UI), లలం (II), గగం (UU); భ (UII), జ (IUI), స (IIU), య (IUU), ర (UIU), త (UUI), న (III), మ (UUU).","ప్రకృతి–వికృతి: శ్రీ–సిరి, రాశి–రాసి, భక్తి–బత్తి, కన్య–కన్నె, ద్యూతం–జూదం, మూర్ఖుడు–మొరకు."]},"qa":[["వేంకటేశ్వరుని పెళ్ళికి ముత్తైదువులుగా వచ్చినవారు?","పార్వతి, సరస్వతి మొదలైనవారు."],["వివాహ కార్యక్రమాలు జరిపినది?","కశ్యప మహర్షి."],["కాశీకి వెళ్తున్న హరిని ఆపినది?","సముద్రుడు (తోయధి) – \"నా కూతురిని ఇస్తాను\" అని."],["కన్యాదానం ఎవరు చేశారు?","సముద్రుడు తన భార్యతో కలిసి."],["హరి ఏం చేశాడు?","రమ చేయి పట్టి (కరగ్రహణం) శంఖం వంటి కంఠంలో మంగళసూత్రం కట్టాడు."],["లాజహోమం అంటే?","పేలాలతో వధువు చేత చేయించే హోమం."]],"act":"మీ కుటుంబాల్లో జరిగే పెళ్ళి విధానాన్ని పెద్దల ద్వారా తెలుసుకొని రాయండి.","kn":"సూక్తి: భారతీయ వివాహ వ్యవస్థ ప్రపంచానికే ఆదర్శం. భారతీయ సంస్కృతి సంప్రదాయాలకు ముగ్ధుడు కాని విదేశీయుడు లేడంటే అతిశయోక్తి లేదు.","qz":[["\"కల్యాణం\" పాఠం కవయిత్రి?","తరిగొండ వెంగమాంబ","ఆతుకూరి మొల్ల","ముద్దుపళని","రంగాజమ్మ"],["ఈ పాఠం ప్రక్రియ?","ద్విపద","పద్యం","వచన కవిత","శతకం"],["పాఠం ఏ గ్రంథం నుండి?","రమాపరిణయం","వేంకటాచల మాహాత్మ్యం","చెంచునాటకం","భాగవతం"],["ప్రాస నియమం లేని ద్విపద?","మంజరీ ద్విపద","కంద ద్విపద","సీస ద్విపద","తరువోజ"],["తరిగొండ వెంగమాంబ ఎవరి భక్తురాలు?","శ్రీ వేంకటేశ్వరస్వామి","శివుడు","రాముడు","నరసింహుడు"],["పెళ్ళి కార్యక్రమం జరిపించిన ముని?","కశ్యపుడు","వశిష్ఠుడు","విశ్వామిత్రుడు","అగస్త్యుడు"],["లక్ష్మీదేవి తండ్రి (పాఠం ప్రకారం)?","సముద్రుడు","ఆకాశరాజు","హిమవంతుడు","జనకుడు"],["హరిని \"కపటనాటక\" అని పిలిచినది?","సముద్రుడు","పార్వతి","కశ్యపుడు","బ్రహ్మ"],["\"దరనిభకంఠం\" అంటే?","శంఖం వంటి కంఠం","తామర వంటి కంఠం","కోయిల కంఠం","నల్లని కంఠం"],["లాజహోమంలో వాడేవి?","పేలాలు","బియ్యం","నెయ్యి మాత్రమే","పూలు"],["\"తోయధి\" అంటే?","సముద్రం","నది","చెరువు","మేఘం"],["ద్యూతం – వికృతి?","జూదం","జూటం","దూతం","జూతి"],["మహా + ఋషి = ?","మహర్షి (గుణ సంధి)","మహాఋషి","మహర్శి","మహేర్షి"],["\"జలజ\" ఏ గణం?","న గణం (III)","భ గణం","స గణం","మ గణం"]],"wb":{"mis":"గురువు (U): దీర్ఘాక్షరం, సున్నా/విసర్గ ఉన్నది, సంయుక్తాక్షరం ముందున్నది; లఘువు (I): హ్రస్వాక్షరం. \"తక్షణం\" లో \"త\" సంయుక్తాక్షరం ముందు ఉంది కాబట్టి గురువు.","qz":[["\"మాయావి\" గణం?","త గణం (UUI)","య గణం","ర గణం","భ గణం"],["\"కలాపి\" గణం?","జ గణం (IUI)","స గణం","ర గణం","య గణం"],["\"సురూపం\" గణం?","య గణం (IUU)","మ గణం","స గణం","త గణం"],["\"అఖిలం\" గణం?","స గణం (IIU)","న గణం","జ గణం","భ గణం"],["ఇచ్చోట విడదీస్తే?","ఈ + చోట (త్రిక సంధి)","ఇ + చోట","ఇచ్ + చోట","ఇత్ + చోట"],["\"కుర్రవాడు గుర్రంమీద… విర్రవీగుతుండగా జర్రున…\" – అలంకారం?","వృత్త్యనుప్రాస","ఉపమ","రూపకం","అతిశయోక్తి"]],"pg":"37–44","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":45,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 37)","అవగాహన – ప్రతిస్పందన (పుట 41)","వ్యక్తీకరణ; పదజాలం (పుట 42)","వ్యాకరణాంశాలు; ఛందస్సు (పుట 43)","గణాలు; ప్రాజెక్టు (పుట 44)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 37)",["1) కుటుంబాలతో ఏర్పడుతుంది 2) కుటుంబ వ్యవస్థ (కుటుంబానికి మూలం పెళ్ళి) 3) సంస్కృతి, సంప్రదాయాలు అందుతాయి (వివాహాల ద్వారా)"]],["అవగాహన – ప్రతిస్పందన (పుట 41)",["1. అ) రాగంతో పాడాలి (ద్విపద – పాటలా పాడవచ్చు) ఆ) కారణాలు: సమయాభావం, ఉద్యోగాలు, ఖర్చు, పట్టణ జీవనం, చిన్న కుటుంబాలు, విదేశీ ప్రభావం, ఫంక్షన్ హాళ్ళు, ఫోటోలు–వీడియోల మోజు; అయిదు రోజుల పెళ్ళి ఒక్క రోజుకు తగ్గింది","2. సరైన క్రమం: ఈ) మనము రంజిల్లగా మధుపర్కమిచ్చి → ఆ) తన వధూయుక్తుడై దానంబు చేసె → ఉ) కరుణించి హరి కరగ్రహణంబు చేసి → అ) సురుచిర మంగళసూత్రంబుం గట్టె → ఇ) వలనొప్ప వేర్వేఱ వరుసగా నడపె","3. 1) వేంకటాచల నివాసుని (శ్రీహరిని) 2) బ్రహ్మ, రుద్రుడు మొదలైన దేవతలు, బంధుజనం 3) తన పురంలోని విడిదులకు 4) శోభన ద్రవ్యాలు (మంగళ ద్రవ్యాలు)"]],["వ్యక్తీకరణ; పదజాలం (పుట 42)",["1. అ) ఉదా: మా అక్క పెళ్ళి – పెళ్ళికూతురిని చేయడం, మంగళస్నానం, పందిరి, గౌరీపూజ, వరుడి రాక (ఎదుర్కోలు), కాశీయాత్ర, కన్యాదానం, జీలకర్ర–బెల్లం, మాంగల్యధారణ, తలంబ్రాలు, అరుంధతీ దర్శనం, విందు – అందరూ ఆనందంగా పాల్గొన్నాం ఆ) సారాంశం: వేంకటేశ్వరుని పెళ్ళికి పార్వతి, సరస్వతి ముత్తైదువులుగా వచ్చారు; కశ్యపుడు కార్యక్రమాలు జరిపాడు; మంగళస్నానం, పుణ్యాహవాచనం, వ్రతాలు జరిగాయి; కాశీయాత్రకు బయలుదేరిన హరిని సముద్రుడు ఆపి మందిరానికి తెచ్చాడు; మధుపర్కం, నగలు, వస్త్రాలు ఇచ్చి కన్యాదానం చేశాడు; హరి మంగళసూత్రం కట్టాడు; తలంబ్రాలు, లాజహోమం జరిగాయి","2. అ) కథ: సముద్రుని కూతురు రమ. ఆమెకు తగిన వరుడు శ్రీహరి అని తండ్రి నిశ్చయించాడు. పెళ్ళి రోజు దేవతలందరూ వచ్చారు. పెళ్ళికొడుకు కాశీకి బయలుదేరితే సముద్రుడు \"నా కూతురిని ఇస్తాను, కాశీ ఎందుకు?\" అని వేడుకొని తీసుకొచ్చాడు. … మంగళసూత్రధారణ, తలంబ్రాలతో కల్యాణం వైభవంగా జరిగింది ఆ) వ్యాసం: భారతీయ వివాహం రెండు కుటుంబాల కలయిక; ప్రతి ఆచారానికి అర్థం ఉంది (పాణిగ్రహణం – జీవితాంతం చేయి వీడను, సప్తపది – ఏడడుగుల స్నేహం, అరుంధతీ దర్శనం – పాతివ్రత్యం); బంధుత్వాలు పెరుగుతాయి; సంస్కృతి తరం నుండి తరానికి చేరుతుంది; ప్రపంచానికే ఆదర్శం","పదజాలం 1. అ) శ్రీ – సిరి ఆ) రాశి – రాసి ఇ) భక్తి – బత్తి ఈ) కన్య – కన్నె/కన్నియ ఉ) ద్యూతం – జూదం ఊ) మూర్ఖుడు – మొరకు","2. అ) ఆభరణాలు = నగలు – అమ్మ పండక్కి నగలు పెట్టుకుంది ఆ) కరములు = చేతులు – చేతులు శుభ్రంగా కడుక్కోవాలి ఇ) ప్రాలు = బియ్యం – బియ్యం కడిగి వండాలి ఈ) సతి = భార్య – రాముని భార్య సీత"]],["వ్యాకరణాంశాలు; ఛందస్సు (పుట 43)",["1. గుణ సంధి: ఆ) సకలోత్సవములు = సకల + ఉత్సవములు ఇ) మహోన్నతుడు = మహా + ఉన్నతుడు ఈ) పురుషోత్తముడు = పురుష + ఉత్తముడు ఊ) మహేంద్రుడు = మహా + ఇంద్రుడు ౠ) మహర్షి = మహా + ఋషి","త్రిక సంధి: అ) ఇచ్చోట = ఈ + చోట ఉ) ఎవ్వారు = ఏ + వారు ఋ) అగ్గజేంద్రము = ఆ + గజేంద్రము ఎ) ఎచ్చోట = ఏ + చోట","2. అ) వృత్త్యనుప్రాస (\"ల్ల\" మళ్ళీ మళ్ళీ) ఆ) వృత్త్యనుప్రాస (\"ర\", \"వ\" మళ్ళీ మళ్ళీ) ఇ) వృత్త్యనుప్రాస (\"ర్ర\" మళ్ళీ మళ్ళీ) ఈ) వృత్త్యనుప్రాస (\"తల\" మళ్ళీ మళ్ళీ)"]],["గణాలు; ప్రాజెక్టు (పుట 44)",["కందులు – UII – భ గణం; మాయావి – UUI – త గణం; జలజ – III – న గణం; అఖిలం – IIU – స గణం; వారేరీ – UUU – మ గణం; తక్షణం – UIU – ర గణం; సురూపం – IUU – య గణం; కలాపి – IUI – జ గణం","ప్రాజెక్టు: మీ కుటుంబంలోని పెళ్ళి విధానం (నిశ్చితార్థం, పెళ్ళికూతురిని చేయడం, ఎదుర్కోలు, కాశీయాత్ర, కన్యాదానం, జీలకర్ర–బెల్లం, మాంగల్యధారణ, తలంబ్రాలు, సప్తపది, అరుంధతీ దర్శనం, అప్పగింతలు) పెద్దల ద్వారా తెలుసుకొని రాయాలి"]]]},{"id":"sl6","no":6,"t":"పిసినారి","m":[9],"ty":"నాటకం","th":"హాస్యం, సామాజిక చైతన్యం","by":"కాళ్ళకూరి నారాయణరావు","sum":"\"వరవిక్రయం\" నాటకం ద్వితీయాంకంలోని ఘట్టం ఇది. సింగరాజు లింగరాజు డబ్బే ప్రపంచమని నమ్మే పిసినారి, వడ్డీ వ్యాపారి – \"ప్రాణం పోయినా పైసా పోనీయకూడదు, ధనమూలమిదం జగత్\" అంటాడు. ఇనుపపెట్టె ఎదుట నిలబడి \"భాగ్యలక్ష్మీ! భార్య, బిడ్డలు, దేవుడు, మోక్షం అన్నీ నీవే\" అని దండకం చదువుతాడు. వంటమనిషి ఘంటయ్యతో బియ్యం, కట్టెలు, పిడకలు, ఉప్పు, మిరపకాయల వంటి చిల్లర లెక్కలు కూడా రాస్తాడు; కట్టెల కోసం కాకిగూడు పడగొట్టమంటాడు. కొడుకు బసవరాజు బండివాడికి అబద్ధం చెప్పనంటే, ఫౌంటెన్ పెన్ను అడిగితే విసుక్కుంటాడు. పెళ్ళిళ్ళ పేరయ్య పురుషోత్తమరావు గారి కుమార్తె సంబంధం తెస్తే \"తిండి తక్కువ తిని, ఇంటిపనులన్నీ చేసి, కొట్టినా పడి ఉండే కన్య కావాలి\" అని, పది ఎకరాల పొలం, కట్నం, వెండి సామాన్లు అడుగుతాడు; చివరకు వేలంపాట ఎత్తుగడతో ఐదువేల కట్నానికి ఒప్పుకుంటాడు. వరకట్న దురాచారాన్ని హాస్యంతో ఎండగట్టిన నాటకం ఇది.","pts":["రచయిత: కాళ్ళకూరి నారాయణరావు (1871–1927) – పశ్చిమగోదావరి జిల్లా; సంఘసంస్కర్త, రచనను ఆయుధంగా స్వీకరించాడు.","నాటకాలు: వరవిక్రయం (1923 – వరకట్నం), మధుసేవ (మద్యపానం), చింతామణి (వేశ్యావృత్తి) – సాంఘిక నాటకాలు; నవలలు, కథలు కూడా రాశాడు.","జగద్గురు శంకరాచార్యులు \"మహాకవి\" బిరుదుతో సత్కరించారు; 27-6-1927 న మరణించాడు.","ప్రక్రియ: నాటకం – \"కావ్యేషు నాటకం రమ్యం\"; పాత్రధారులు ఆహార్యంతో రంగస్థలంపై ప్రదర్శించే కళ; నాటకంలోని భాగాలను \"అంకాలు\" అంటారు.","పాత్రలు: లింగరాజు (పెళ్ళికొడుకు తండ్రి), బసవరాజు (పెళ్ళికొడుకు), ఘంటయ్య (వంటమనిషి), పెళ్ళిళ్ళ పేరయ్య.","లింగరాజు మూడు పెళ్ళిళ్ళకు 2000 + 4000 + 8000 = 14,000 కట్నం తీసుకున్నాడు.","గురజాడ అప్పారావు \"కన్యాశుల్కం\" – కళ కళ కోసమే కాదు, సాంఘిక ప్రయోజనం ఉందని నిరూపించిన నాటకం."],"w":[["పిసినారి","లోభి, కృపణుడు"],["స్థిమితము","నెమ్మది"],["ధనమూలమిదం జగత్","ఈ ప్రపంచానికి ధనమే మూలం"],["దివాలా","అప్పులు తీర్చలేని స్థితి"],["కల్లలు","అబద్ధాలు"],["వాటమైన","అనువైన"],["నిరాహారి","ఆహారం తీసుకోనివాడు"],["పద్దు","లెక్క"],["ఉద్ధరిణెడు","చిన్న చెంచా పరిమాణం"],["ఉద్వాసన","పని నుండి తొలగించడం"],["తనఖా","తాకట్టు"],["రొక్కము","నగదు"],["అలుకపాన్పు","పెళ్ళి తర్వాత అల్లుడు అలిగి కానుకలు కోరే పాన్పు"],["అంపకాలు","అప్పగింతలు"],["బయానా","ఒప్పందానికి ఇచ్చే ముందస్తు డబ్బు"]],"gr":{"t":"భాషాంశాలు","p":["అవ్యయీభావ సమాసం: పూర్వపదం అవ్యయం (లింగ, వచన, విభక్తులు లేనిది), పూర్వపదార్థం ప్రధానం – యథాశక్తి (శక్తిననుసరించి), ప్రతిదినము (దినము దినము), ఆపాదమస్తకం (పాదం నుండి మస్తకం వరకు), ఆసేతుశీతాచలం (సేతువు నుండి హిమాలయం వరకు).","షష్ఠీ తత్పురుష: నా యిల్లు (నా యొక్క ఇల్లు); సప్తమీ తత్పురుష: వేలంపాట (వేలమునందు పాట).","ప్రకృతి–వికృతి: రాత్రి–రాతిరి, కన్య–కన్నియ.","నాటక పరిభాష: ప్రవేశము, నిష్క్రమించును, తెరపడును, అంకము, స్వగతం (\"తనలో\"), పయికి (బహిరంగంగా)."]},"qa":[["లింగరాజు ధనం గురించి ఏమన్నాడు?","ప్రాణం పోయినా పైసా పోనీయకూడదు; \"ధనమూలమిదం జగత్\" – ప్రపంచమంతా ధనంలోనే ఉంది."],["లింగరాజు ఎవరిని ప్రార్థించాడు? ఎలా?","ఇనుపపెట్టె ఎదుట భాగ్యలక్ష్మిని – \"భార్య, బిడ్డలు, దేవుడు, మోక్షం అన్నీ నీవే\" అని దండకంతో."],["ఘంటయ్యకు లింగరాజు చెప్పిన పాపపు పని?","కరివేప చెట్టుపై ఉన్న కాకిగూడును పడగొట్టి వంటచెరకుగా వాడమని."],["లింగరాజు కోరిన కన్య లక్షణాలు?","తిండి తక్కువ తినాలి, చెప్పకుండానే ఇంటిపనులన్నీ చేయాలి, కొట్టినా పడి ఉండాలి."],["చివరకు కుదిరిన కట్నం?","ఐదువేల ఐదువందల రూపాయలు (పేరయ్య వాటా 500 తో సహా) + వెండి సామాన్లు, లాంఛనాలు."],["ఈ నాటకం ఏ దురాచారాన్ని ఖండిస్తుంది?","వరకట్నం (వరవిక్రయం)."]],"act":"\"పిసినారి\" పాఠాన్ని పాత్రలు పంచుకొని పాఠశాల వార్షికోత్సవంలో నాటకంగా ప్రదర్శించండి; వరకట్న నిర్మూలనపై కరపత్రం తయారుచేయండి.","kn":"వరకట్న నిషేధ చట్టం – 1961. వరకట్నం అడగడం, ఇవ్వడం రెండూ నేరం.","qz":[["\"పిసినారి\" పాఠ రచయిత?","కాళ్ళకూరి నారాయణరావు","గురజాడ అప్పారావు","ఉషశ్రీ","ఇస్మాయిల్"],["ఈ పాఠం ఏ నాటకం నుండి?","వరవిక్రయం","కన్యాశుల్కం","మధుసేవ","చింతామణి"],["వరవిక్రయం ఏ దురాచారంపై?","వరకట్నం","కన్యాశుల్కం","మద్యపానం","బాల్యవివాహం"],["కాళ్ళకూరికి \"మహాకవి\" బిరుదు ఇచ్చినది?","జగద్గురు శంకరాచార్యులు","ఆంధ్ర విశ్వవిద్యాలయం","ప్రభుత్వం","గురజాడ"],["పాఠంలో పిసినారి ఎవరు?","లింగరాజు","బసవరాజు","ఘంటయ్య","పేరయ్య"],["లింగరాజు వంటమనిషి?","ఘంటయ్య","పేరయ్య","వీరయ్య","బసవరాజు"],["లింగరాజు ఇనుపపెట్టె ముందు ఎవరిని ప్రార్థించాడు?","భాగ్యలక్ష్మి","సరస్వతి","శివుడు","గణపతి"],["పక్షిగూడు పడగొట్టడం పాపం అన్నది?","ఘంటయ్య","లింగరాజు","బసవరాజు","పేరయ్య"],["బసవరాజు తండ్రిని అడిగినది?","ఫౌంటెన్ పెన్ను","సైకిలు","కొత్త బట్టలు","పుస్తకాలు"],["లింగరాజు మూడు పెళ్ళిళ్ళ మొత్తం కట్నం?","పదునాలుగువేలు","పదివేలు","ఎనిమిదివేలు","ఇరవైవేలు"],["పేరయ్య తెచ్చిన సంబంధం ఎవరి కుమార్తె?","పుణ్యమూర్తుల పురుషోత్తమరావు","సింగరాజు","వీరయ్య","వెంకటాయలు"],["కట్నం పెంచడానికి పేరయ్య ఎత్తుగడ?","వివాహాల వీరయ్యతో వేలంపాట","కోర్టుకు వెళ్ళడం","పత్రికా ప్రకటన","పంచాయితీ"],["\"ఉద్వాసన\" అంటే?","పని నుండి తొలగించడం","స్వాగతం","భోజనం","విశ్రాంతి"],["\"యథాశక్తి\" సమాసం?","అవ్యయీభావ","ద్వంద్వ","ద్విగు","షష్ఠీ తత్పురుష"]],"wb":{"mis":"అవ్యయీభావంలో పూర్వపదం (యథా, ప్రతి, ఆ) అవ్యయం, దాని అర్థమే ప్రధానం; \"నా యిల్లు\" లో నా సర్వనామం – అది షష్ఠీ తత్పురుష.","qz":[["\"ఆపాదమస్తకం\" విగ్రహం?","పాదం నుండి మస్తకం వరకు","పాదము, మస్తకము","పాదము యొక్క మస్తకం","పాదము లేని మస్తకం"],["\"ఆసేతుశీతాచలం\" విగ్రహం?","సేతువు నుండి శీతాచలం వరకు","సేతువు, శీతాచలం","సేతువు యొక్క శీతాచలం","శీతాచలం లేని సేతువు"],["\"నా యిల్లు\" సమాసం?","షష్ఠీ తత్పురుష","అవ్యయీభావ","ద్వంద్వ","బహువ్రీహి"],["\"ప్రతిదినము\" విగ్రహం?","దినము దినము","ప్రతి యొక్క దినము","దినము లేనిది","దినము కొరకు"],["\"కన్నియ\" ప్రకృతి?","కన్య","కనియ","కన్నె","కనక"],["\"వాంఛ\" పర్యాయపదం?","కోరిక, ఇచ్ఛ","భయం, బెదురు","కోపం, క్రోధం","సుఖం, హాయి"]],"pg":"45–58","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":53,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 45)","అవగాహన – ప్రతిస్పందన (పుట 56)","వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 57)","ప్రకృతి–వికృతి, పర్యాయపదాలు, సమాసాలు; ప్రాజెక్టు (పుట 58)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 45)",["1) గురజాడ అప్పారావు రాసిన \"కన్యాశుల్కం\" నాటకం గురించి 2) కళ కళ కోసమే కాదు, దానికి సాంఘిక ప్రయోజనం, బాధ్యత ఉంది – కన్యాశుల్కం ఆ దురాచారాన్ని రూపుమాపడానికి తోడ్పడింది 3) వరవిక్రయం, మధుసేవ, చింతామణి (కాళ్ళకూరి), కన్యాశుల్కం (గురజాడ), మా భూమి (సుంకర, వాసిరెడ్డి)"]],["అవగాహన – ప్రతిస్పందన (పుట 56)",["1. అ) ఉదా: మా ఊరిలో ఒక వడ్డీ వ్యాపారి – పిసినారుల వల్ల కుటుంబ సభ్యులు సరిగా తిండి, చదువు, వైద్యం లేక బాధపడతారు; బంధుమిత్రులు దూరమవుతారు; పేదలను ఎక్కువ వడ్డీతో పీడిస్తారు; సమాజంలో గౌరవం ఉండదు ఆ) లింగరాజు చెంపలు వేసుకొని ఇనుపపెట్టె ఎదుట చేతులు జోడించి \"భగవతీ! భాగ్యలక్ష్మీ! నేను నీ దాసుడను; భార్య, బిడ్డలు, దేవుడు, మోక్షం అన్నీ నీవే; నీ కోసం నిరాహారిగా ఉంటాను, నిద్ర మానుతాను, అబద్ధ ప్రమాణాలు చేస్తాను; ఈ పెట్టే నీ ఆలయం, నేనే అర్చకుడను; ఇతరుల ఇళ్ళు ఊడ్చి నా ఇంటికి తెచ్చి ఇవ్వు\" అని దండకంతో ప్రార్థించాడు","2. అ) లింగరాజు తనలో తాను (స్వగతం) – ప్రాణాల కంటే ధనం గొప్పదని అనుకుంటున్న సందర్భం ఆ) ఘంటయ్య లింగరాజుతో – కాకిగూడు పడగొట్టి వంటచెరకుగా వాడమన్నప్పుడు ఇ) పేరయ్య లింగరాజుతో – లింగరాజు పది ఎకరాలు, కట్నం, వెండి సామాన్లు అడిగినప్పుడు","3. అ) బియ్యం – మానెడుకు మణిమెడు తక్కువ; వంటకట్టెలు – మూడు; పిడకలు – రెండు; నిప్పుపుల్ల – సగం; ఉప్పు – ఉద్ధరిణెడు; చింతపండు – నిల్వ ఉన్న తుక్కు; మిరపకాయలు – మూడు; మాగాయ – అమ్మగారికో టెంక, అబ్బాయిగారికో ముక్క; గంజి – గరిటెడు, అరగరిటెడు ఆ) తిండి కొంచెం వెలితిగా తినాలి; చెప్పకుండానే ఇంటిపనులన్నీ చేయాలి; ఊరికే కొట్టినా పడి ఉండాలి – అలాంటి కన్యను వెతికి తేవాలి ఇ) పది ఎకరాల పొలం వ్రాసి ఇవ్వాలి, వేయిన్నూట పదహార్లు రొక్కం, వెండి చెంబు, వెండి కంచం, వెండి పావుకోళ్ళు, అయిదు పట్టుతాబితాలు; చివరకు కనీసం ఐదువేలు కట్నం (పేరయ్య ఐదువందలు అదనంగా) బేరానికి సానుకూలత చూపాడు","4. అ) ఐదువేల ఐదువందల రూపాయల రొక్కం (+ రవ్వల ఉంగరం, వెండి సామాన్లు) ఆ) ప్రతిపూట పెండ్లివారిని బ్యాండుతో పిలవాలి; రాకపోకలకు బండ్లు, రాత్రులు దివిటీలు; రెండుసార్లు పిండివంటలతో భోజనం, మూడుసార్లు కాఫీ, సోడా, ఉప్మా, ఇడ్లీ, దోసె, రవ్వలడ్డు, కాజా, మైసూరుపాకులతో ఫలహారాలు – ఐదు రోజులు ఇ) తమకు పట్టుబట్టలు, తమతో వచ్చేవారికి ఉప్పాడ బట్టలు ఈ) పది రూపాయలు"]],["వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం (పుట 57)",["1. అ) కొంతవరకే వాస్తవం – తిండి, చదువు, వైద్యం, ఇల్లు అన్నిటికీ ధనం అవసరం; కానీ ధనమే అంతా కాదు; ఆరోగ్యం, ప్రేమ, స్నేహం, విలువలు, గౌరవం డబ్బుతో కొనలేం; ధనం కోసం లింగరాజులా దిగజారకూడదు ఆ) అత్యాశాపరులు ఇతరులను మోసం చేస్తారు, ఎక్కువ వడ్డీలు వేస్తారు, దొంగ లెక్కలతో పన్ను ఎగ్గొడతారు, ఆస్తులు భార్య పేర రాసి మాయ దివాలా తీస్తారు, పెళ్ళిని బేరంగా మారుస్తారు, కుటుంబాన్ని కూడా పట్టించుకోరు ఇ) ఆడపిల్ల తల్లిదండ్రులు కట్నం కోసం అప్పులు చేసి, ఆస్తులు అమ్మి బాధపడతారు; మగపిల్లవాడి తల్లిదండ్రులు గౌరవం, చదువు పేరుతో ఎక్కువ కట్నం ఆశిస్తారు; కొందరు కట్నం లేకుండా గుణవంతులైన కోడళ్ళను కోరుతున్నారు – అదే సరైన ఆలోచన","2. అ) లింగరాజు మహా పిసినారి; ధనమే దైవమని నమ్మేవాడు; ఇనుపపెట్టెనే గుడిగా భావించాడు; వడ్డీ వ్యాపారి – అప్పుగొన్నవారి ఆస్తులు కాజేస్తాడు; దొంగలెక్కలతో పన్ను ఎగ్గొడతాడు; ఇంట్లో ఉప్పు, మిరపకాయల వరకు లెక్క చూస్తాడు; దయ లేనివాడు – కాకిగూడు పడగొట్టమన్నాడు; కొడుకును అబద్ధాలాడమన్నాడు; మూడు పెళ్ళిళ్ళకు కట్నాలు పిండుకున్నాడు; కొడుకు పెళ్ళినీ బేరంగా మార్చాడు; కోడలిని పనిమనిషిగా భావించాడు – ధనాశకు ప్రతిరూపం","3. అ) నాటకంగా ప్రదర్శించాలి (లింగరాజు, ఘంటయ్య, బసవరాజు, పేరయ్య పాత్రలు) ఆ) లేఖ: \"ప్రియమైన మిత్రుడు శ్రీను, … కందుకూరి వీరేశలింగం గారు/కాళ్ళకూరి నారాయణరావు గారు వరకట్నం వంటి దురాచారాలను రచనలతో, ఉద్యమాలతో ఎదిరించారు; వారి కృషిని అభినందిద్దాం…\" ఇ) కరపత్రం: \"వరకట్నం వద్దు – వధువే వరం! కట్నం అడగడం, ఇవ్వడం నేరం (1961 చట్టం). ఆడపిల్లను చదివించండి – అదే నిజమైన కట్నం. కట్నం అడిగితే 100/181 కి ఫోన్ చేయండి\"","పదజాలం 1. అ) నిరాహారి = ఆహారం తీసుకోనివాడు ఆ) ఉద్వాసన = పని నుండి తొలగించడం ఇ) పరదేశ బ్రాహ్మణుడు = వేరే ఊరి నుండి వచ్చిన (యాచక) బ్రాహ్మణుడు ఈ) తృణమో కణమో = కొంచెమో గొప్పో"]],["ప్రకృతి–వికృతి, పర్యాయపదాలు, సమాసాలు; ప్రాజెక్టు (పుట 58)",["2. అ) రాత్రి – రాతిరి ఆ) కన్నియ – కన్య","3. అ) వాంఛ = కోరిక, ఇచ్ఛ, అభిలాష ఆ) పాన్పు = పడక, శయ్య","సమాసాలు 1. అ) నా యిల్లు – నా యొక్క ఇల్లు (షష్ఠీ తత్పురుష) ఆ) బంగారపుతునక – బంగారము యొక్క తునక (షష్ఠీ తత్పురుష) ఇ) వేలంపాట – వేలమునందు పాట (సప్తమీ తత్పురుష)","అవ్యయీభావ: అ) మధ్యాహ్నం – అహ్నము (పగలు) యొక్క మధ్య భాగం ఆ) ఆసేతుశీతాచలం – సేతువు నుండి శీతాచలం (హిమాలయం) వరకు","ప్రాజెక్టు: వరకట్న దురాచారంపై వార్తలు, గణాంకాలు, చట్టాలు సేకరించి నివేదిక/ప్రదర్శన"]]]},{"id":"sl7","no":7,"t":"మనిషీ! మనిషీ!","m":[9],"ty":"వచన కవిత","th":"సామాజిక చైతన్యం","by":"ఇస్మాయిల్","sum":"కవి మనిషికి ప్రకృతి నుండి పాఠాలు చెబుతున్నాడు. ఓ మనిషీ! సరిహద్దులు లేని ఆకాశంలో ఎత్తుగా ఎగిరే డేగను చూడు – అది గిరిగీసుకొని కూర్చోదు; భూచక్రాన్ని తన ముక్కు చివర తిప్పుతున్నట్లు ఎగురుతుంది; స్ఫుటంగా, తీక్షణంగా చూసే సూర్యుడే దానికి ఆదర్శం. పిట్టలకు ఎగరడం నేర్పిన చెట్టును చూడు – అది ఏ భాషలో పూస్తుంది? (భేదం లేకుండా అంతటా ఒకేలా పూస్తుంది). వరిమళ్ళలో ఈదే చిరు ఆకాశాలనూ చిట్టిపరిగలనూ చూడు – ఆ ఆనందపు రంగులు చైనా, వియత్నాం, జపాన్ పొలాల్లో ఎక్కడైనా అవే. ఉప్పు ఏ భాషలోనైనా ఉప్పగానే ఉంటుంది. అలాగే మనిషి కూడా కుల, మత, ప్రాంత, భాషా భేదాలు, సరిహద్దులు లేకుండా అందరితో స్నేహంగా, ప్రేమగా మెలగాలని కవి సందేశం.","pts":["కవి: ఇస్మాయిల్ (1928–2003) – తూర్పుగోదావరి జిల్లా; అనుభూతివాద కవుల్లో ప్రసిద్ధుడు; కాకినాడ కళాశాలలో తత్వశాస్త్ర అధ్యాపకుడు.","కవితా సంపుటాలు: చిలుకలు వాలిన చెట్టు, మృత్యువృక్షం, రాత్రి వచ్చిన రహస్యపు వాన, చెట్టు నా ఆదర్శం.","సహృదయులు ఆయనను \"చెట్టు కవి\" అని పిలుచుకుంటారు; సరళమైన పదాల్లో సంక్షిప్తమైన గాఢ భావాలు.","పాఠం \"ఇస్మాయిల్ కవితలు\" సంకలనం నుండి. ప్రక్రియ: వచన కవిత.","ప్రతీకలు: డేగ – స్వేచ్ఛ, ఉన్నతి; సూర్యుడు – అందరికీ సమానంగా వెలుగు; చెట్టు – ఆశ్రయం, నిస్వార్థం; ఉప్పు – భాష మారినా గుణం మారదు.","సందేశం: సరిహద్దులు, భేదాలు లేని విశ్వమానవత్వం."],"w":[["సరిహద్దు","హద్దు, సీమ"],["గిరిగీసుకొను","హద్దు పెట్టుకొను"],["చుంచుకాగ్రం","ముక్కు చివర"],["స్ఫుటంగా","స్పష్టంగా"],["తీక్షణంగా","చురుకుగా, వాడిగా"],["వీక్షించు","చూచు"],["సూర్యనేత్రం","సూర్యుడనే కన్ను"],["ఆదర్శం","అనుసరించదగినది"],["పరిగ","చిన్న చేప"],["పుష్పించు","పూయు"],["భూచక్రం","భూమండలం"],["పరిమళం","సువాసన"],["వినీల","మిక్కిలి నీలమైన"],["బాస","భాష"],["ఆకసం","ఆకాశం"]],"gr":{"t":"భాషాంశాలు","p":["అతిశయోక్తి అలంకారం: ఉన్నదానికంటే ఎక్కువ చేసి చెప్పడం – \"భవనాలు ఆకాశాన్ని తాకుతున్నాయి\"; \"భూచక్రాన్ని గుండ్రంగా చుంచుకాగ్రంపై తిప్పుతుంది\".","సామాన్య వాక్యం: ఒకే సమాపక క్రియ – \"బాలు మైదానానికి వెళ్ళాడు\". సంశ్లిష్ట వాక్యం: అసమాపక క్రియతో రెండు వాక్యాలు కలిసినది – \"వినీత్ గ్రంథాలయానికి వెళ్ళి, మంచి పుస్తకం తెచ్చాడు\".","గణాలు: మనిషీ (IIU – స), ఎత్తుగా (UIU – ర), స్ఫుటంగా (IUU – య), ఇస్మాయిల్ (UUU – మ). చంపకమాల: న జ భ జ జ జ ర.","వికృతి–ప్రకృతి: బాస–భాష, ఆకసం–ఆకాశం."]},"qa":[["డేగ ఆదర్శం ఏది?","స్ఫుటంగా, తీక్షణంగా చూసే సూర్యనేత్రం (సూర్యుడు)."],["చెట్టు ఎవరికి ఎగరడం నేర్పింది?","పిట్టలకు."],["ఆనందపు రంగులు ఎక్కడ కనిపిస్తాయి?","వరిమళ్ళలో ఈదే చిరు ఆకాశాల్లో, చిట్టిపరిగల్లో – చైనా, వియత్నాం, జపాన్ పొలాల్లో ఎక్కడైనా."],["ఉప్పు ఉదాహరణ ద్వారా కవి ఏం చెప్పాడు?","భాష మారినా వస్తువు గుణం మారదు; మనిషి కూడా ఎక్కడైనా మనిషే – భేదాలు అనవసరం."],["కవి సందేశం?","సరిహద్దులు, భేదాలు లేకుండా మనుషులంతా ప్రేమతో, స్నేహంతో మెలగాలి."],["ఇస్మాయిల్‌ను ఏమని పిలుస్తారు?","చెట్టు కవి."]],"act":"\"జీవితం కరిగిపోయే మంచు – ఉన్నదాంట్లో నలుగురికీ పంచు\" సూక్తి ఆధారంగా ప్రకృతి నుండి మనం నేర్చుకోవాల్సిన విషయాలపై కవితలు సేకరించి/రాసి ప్రదర్శించండి.","kn":"సూక్తి: జీవితం కరిగిపోయే మంచు – ఉన్నదాంట్లో నలుగురికీ పంచు.","qz":[["\"మనిషీ! మనిషీ!\" కవి?","ఇస్మాయిల్","పల్లా దుర్గయ్య","శ్రీశ్రీ","గుర్రం జాషువా"],["ఇస్మాయిల్‌ను ఏమని పిలుస్తారు?","చెట్టు కవి","ప్రజాకవి","అభినవ పోతన","కవిసామ్రాట్"],["ఇస్మాయిల్ ఏ కవితా వాదానికి చెందినవాడు?","అనుభూతివాదం","విప్లవవాదం","దిగంబర","భావకవిత్వం"],["ఇస్మాయిల్ రచన?","చెట్టు నా ఆదర్శం","పాలవెల్లి","గంగిరెద్దు","మహాప్రస్థానం"],["ఈ పాఠం ప్రక్రియ?","వచన కవిత","పద్యం","ద్విపద","నాటకం"],["ఎత్తుగా ఆకాశంలో ఎగిరేది?","డేగ","కాకి","చిలుక","పావురం"],["డేగ ఆదర్శం?","సూర్యనేత్రం","చంద్రుడు","చెట్టు","మేఘం"],["పిట్టలకు ఎగరటం నేర్పినది?","చెట్టు","డేగ","గాలి","తల్లి పక్షి"],["\"ఉప్పు ఏ భాషలోనైనా…\"","ఉప్పగానే ఉంటుంది","తియ్యగా ఉంటుంది","మారుతుంది","కారంగా ఉంటుంది"],["వరిమళ్ళలో ఈదేవి?","చిరు ఆకాశాలు, చిట్టిపరిగలు","కప్పలు","బాతులు","పడవలు"],["\"చుంచుకాగ్రం\" అంటే?","ముక్కు చివర","రెక్క చివర","తోక","కాలి గోరు"],["\"భవనాలు ఆకాశాన్ని తాకుతున్నాయి\" – అలంకారం?","అతిశయోక్తి","ఉపమ","అంత్యానుప్రాస","రూపకం"],["బాస – ప్రకృతి?","భాష","బాష","భాస","వాస"],["\"మనిషీ\" గణం?","స గణం (IIU)","య గణం","ర గణం","న గణం"]],"wb":{"mis":"సంశ్లిష్ట వాక్యంలో అసమాపక క్రియ (వెళ్ళి, చూసి) + సమాపక క్రియ ఉంటాయి; సామాన్య వాక్యంలో ఒకే సమాపక క్రియ. గణాల్లో సంయుక్తాక్షరం ముందున్న అక్షరం గురువు (ఎ-త్తు: \"ఎ\" గురువు).","qz":[["\"బాలు మైదానానికి వెళ్ళాడు\" – వాక్యం?","సామాన్య వాక్యం","సంశ్లిష్ట వాక్యం","సంయుక్త వాక్యం","ప్రశ్నార్థకం"],["\"వినీత్ గ్రంథాలయానికి వెళ్ళి, మంచి పుస్తకం తెచ్చాడు\" – వాక్యం?","సంశ్లిష్ట వాక్యం","సామాన్య వాక్యం","నిషేధార్థకం","ఆశ్చర్యార్థకం"],["\"ఎత్తుగా\" గణం?","ర గణం (UIU)","స గణం","య గణం","జ గణం"],["\"స్ఫుటంగా\" గణం?","య గణం (IUU)","ర గణం","మ గణం","భ గణం"],["\"ఇస్మాయిల్\" గణం?","మ గణం (UUU)","త గణం","న గణం","స గణం"],["\"నేత్రం\" పర్యాయపదాలు?","కన్ను, నయనం","చేయి, కరం","చెట్టు, తరువు","పువ్వు, కుసుమం"]],"pg":"59–64","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":67,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 59)","అవగాహన – ప్రతిస్పందన (పుట 62)","పాఠ ప్రశ్నలు; వ్యక్తీకరణ; పదజాలం (పుట 63)","వ్యాకరణాంశాలు; అతిశయోక్తి (పుట 64)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 59)",["1) ఆధునిక మనిషి సౌకర్యాల కోసం పరుగుపందెంలో పడి జీవితాన్ని ఆస్వాదించడం, సాటిమనిషితో స్నేహంగా మెలగడం మరిచిపోతున్నాడు; ఆ దూరాన్ని తొలగించాలని కవులు తపనపడతారు 2) వస్తువులను సమకూర్చుకొని విలాసవంతంగా బతకాలని పరుగులు తీస్తున్నాడు; సాటిమనిషికి దూరమవుతున్నాడు 3) మనుషుల మధ్య దూరం తొలగి, జీవితాన్ని ఆస్వాదిస్తూ స్నేహభావంతో బతకాలని కవితాత్మకంగా చెబుతూ తపనపడతాడు"]],["అవగాహన – ప్రతిస్పందన (పుట 62)",["1. అ) పక్షుల్లా స్వేచ్ఛగా ఎగరాలనిపిస్తుంది; వాటికి సరిహద్దులు, భేదాలు లేవు – మనమూ అలా ఉండాలనిపిస్తుంది ఆ) ఉదా: మా అమ్మ / మా ఉపాధ్యాయుడు / అబ్దుల్ కలాం – నిస్వార్థంగా అందరికీ సాయం చేస్తారు, ప్రేమగా మాట్లాడతారు","2. అ) \"స్ఫుటంగా తీక్షణంగా వీక్షించే సూర్యనేత్రం దాని ఆదర్శం\" ఆ) \"మనిషీ మనిషీ ఉప్పు ఏ భాషలోనైనా ఉప్పగానే ఉంటుంది\"","3. అ) డేగకు సరిహద్దులు లేవు, హద్దులు పెట్టుకోదు, ఎత్తుగా ఎగురుతుంది – మనిషి కూడా సంకుచిత భావాలు వదిలి, ఉన్నతంగా ఎదిగి, విశాలంగా ఆలోచించాలని చెప్పడానికి"]],["పాఠ ప్రశ్నలు; వ్యక్తీకరణ; పదజాలం (పుట 63)",["ఆ) వరిమళ్ళ నీటిలో ప్రతిబింబించే చిరు ఆకాశాల్లో, చిట్టిపరిగల్లో – చైనా, వియత్నాం, జపాన్ పొలాల్లో ఎక్కడైనా ఇ) \"పిట్టలకు ఎగరటం నేర్పిన చెట్టు ఏ భాషలో పుష్పిస్తుంది?\" అని – చెట్టుకు భాషాభేదం లేదని ఈ) సరళమైన పదాలతో, ప్రకృతి ఉదాహరణలతో గొప్ప విశ్వమానవ సందేశం ఇచ్చిన కవిత; చిన్న వాక్యాలు, గాఢమైన భావం – నాకు చాలా నచ్చింది","వ్య.1. అ) మనుషులు కుల, మత, భాషా, దేశ సరిహద్దులు వదిలి, ప్రకృతిలా అందరితో సమానంగా, ప్రేమగా మెలగాలి – ఇదే ముఖ్య విషయం ఆ) చెట్టు పిట్టలకు నివాసం, ఆశ్రయం ఇస్తుంది; దాని కొమ్మల మీదే పిట్టలు ఎగరడం నేర్చుకుంటాయి – అంటే పెద్దలు పిల్లలకు ఆశ్రయమిచ్చి, స్వతంత్రంగా ఎదిగేలా నేర్పాలి; నిస్వార్థంగా సాయపడాలి ఇ) సూర్యుడు భేదం లేకుండా అందరికీ వెలుగు పంచుతాడు, క్రమశిక్షణతో ఉదయిస్తాడు, స్పష్టంగా చూస్తాడు – మనిషి కూడా అలా అందరికీ సమానంగా మేలు చేయాలని","2. అ) సారాంశం: ఓ మనిషీ! సరిహద్దులు లేకుండా ఎత్తుగా ఎగిరే డేగను చూడు; దానికి సూర్యుడే ఆదర్శం. పిట్టలకు ఎగరడం నేర్పే చెట్టు ఏ భాషలోనైనా ఒకేలా పూస్తుంది. వరిమళ్ళలోని ఆనందపు రంగులు చైనా, వియత్నాం, జపాన్ – ఎక్కడైనా అవే. ఉప్పు ఏ భాషలోనైనా ఉప్పగానే ఉంటుంది. కాబట్టి మనిషి భేదాలు వదిలి అందరితో కలిసి మెలగాలి ఆ) మనిషి డేగలా ఉన్నతంగా, స్వేచ్ఛగా ఎదగాలి; సూర్యుడిలా అందరికీ మేలు చేయాలి; చెట్టులా ఆశ్రయమివ్వాలి, నిస్వార్థంగా ఉండాలి; ప్రకృతిలా ఆనందం పంచాలి; భాష, కులం, మతం, దేశం పేరుతో విభేదాలు పెట్టుకోకూడదు; ఉప్పులా తన మంచి గుణాన్ని ఎక్కడైనా నిలుపుకోవాలి","3. అ) లేఖ: \"ప్రియమైన మిత్రుడు రవికి, … ఇస్మాయిల్ గారి \"మనిషీ! మనిషీ!\" కవిత చదివాను. డేగ, చెట్టు, ఉప్పు వంటి చిన్న ఉదాహరణలతో గొప్ప సందేశం ఇచ్చారు. సరళమైన పదాలు, చిన్న వాక్యాలు – చదవగానే అర్థమవుతుంది. అందుకే ఆయనను \"చెట్టు కవి\" అంటారు. నువ్వూ తప్పక చదువు… ఇట్లు, నీ మిత్రుడు\"","పదజాలం 1. అ) సూర్యుడు = భానుడు, రవి ఆ) నేత్రం = కన్ను, నయనం ఇ) చెట్టు = వృక్షం, తరువు ఈ) ఆకాశం = గగనం, నింగి ఉ) పుష్పం = పువ్వు, కుసుమం","2. బాస – భాష; ఆకసం – ఆకాశం"]],["వ్యాకరణాంశాలు; అతిశయోక్తి (పుట 64)",["1. అ) సంశ్లిష్ట వాక్యం (వెళ్ళి + తెచ్చాడు) ఆ) సంశ్లిష్ట వాక్యం (వెళ్ళి + వచ్చింది) ఇ) సంశ్లిష్ట వాక్యం (ఎక్కి + దాటారు) ఈ) సామాన్య వాక్యం","2. అ) మనిషీ – IIU – స గణం ఆ) ఎత్తుగా – UIU – ర గణం ఇ) స్ఫుటంగా – IUU – య గణం ఈ) ఇస్మాయిల్ – UUU – మ గణం ఉ) గడన / మొనర్చి / యిప్పటి / కిఁగాలి / డఁగల్గి / తినింటి / లోపలన్ = న / జ / భ / జ / జ / జ / ర – చంపకమాల పద్యపాదం","అతిశయోక్తి: డేగ భూమండలాన్ని తన ముక్కు చివర గుండ్రంగా తిప్పడం అసాధ్యం; డేగ చాలా ఎత్తుకు ఎగిరి భూమి అంతా చుట్టి వస్తుందని ఉన్నదానికంటే ఎక్కువ చేసి చెప్పారు – కాబట్టి అతిశయోక్తి అలంకారం","ప్రాజెక్టు: ప్రకృతి, మానవత్వం గురించిన కవితలు సేకరించి ప్రదర్శించాలి"]]]},{"id":"sl8","no":8,"t":"జానపద నృత్య సంగీతాలు","m":[10],"ty":"వ్యాసం (ప్రసంగ వ్యాసం)","th":"సంస్కృతి, కళలు","by":"దేవులపల్లి రామానుజరావు","sum":"పుస్తక విజ్ఞానం, ఆధునిక నాగరికతతో సంబంధం లేకుండా పల్లెల్లో నివసించే ప్రజలే జానపదులు. వారి జీవితంలో సాహిత్యానికి, నృత్య సంగీతాలకు గొప్ప ప్రాధాన్యం ఉంది. లక్షణ గ్రంథాలకు అతీతమైన వారి నృత్య సంగీతాలలో మన సంస్కృతి, భారత భాగవత రామాయణాల ప్రభావం కనిపిస్తుంది. యక్షగానాలు జానపద నృత్య సంగీతాల నుండే పుట్టి నాటకాలుగా మారాయి; పగటివేషాలు, తోలుబొమ్మలు, కురవంజి, బొబ్బిలికథ, బాలనాగమ్మ కథ, కోలాటం, ఒప్పులకుప్ప వంటివి ప్రసిద్ధం. పొలంలో, కోతల్లో, పిండి విసురుతూ, ఊయల ఊపుతూ పాడే పాటలు (దేశీ సంగీతం) – ప్రభాత పదాలు, వెన్నెల పదాలు, లాలిపాటలు, జోలపాటలు, ఏలపాటలు, సుద్దులు, అప్పగింత పాటలు. గజ్జెలు, కొమ్ము, పిల్లనగ్రోవి, నాగస్వరం, అందెలు, తాళాలు, జమిడికలు వారి వాద్యాలు. బాలసంతులు, బుడబుక్కలవారు, జంగాలు, దాసరులు, పిచ్చుకగుంటులు వంటి కళాకారుల తెగలు ఆదరణ లేక తగ్గిపోతున్నాయి – ఈ కళలను కాపాడుకోవడం మన కర్తవ్యం.","pts":["రచయిత: దేవులపల్లి రామానుజరావు (1917–1993) – వరంగల్ సమీపంలోని దేశాయిపేట; ఆంధ్ర సారస్వత పరిషత్తు రథసారథి.","నిజాం కళాశాల నుండి 1939లో బి.ఎ., 1944లో నాగపూర్ విశ్వవిద్యాలయం నుండి న్యాయశాస్త్ర డిగ్రీ; పాత్రికేయుడు, పత్రికా సంపాదకుడు; ఆంధ్ర సాహిత్య అకాడమీ ప్రథమ కార్యదర్శి.","రచనలు: పచ్చతోరణం, సారస్వత నవనీతం, ఉపన్యాసతోరణం, తెనుగు సాహితి, వేగుచుక్కలు మొదలైన ఇరవై గ్రంథాలు.","ప్రక్రియ: ప్రసంగ వ్యాసం – ప్రముఖుల ఉపన్యాసాలను పత్రికల్లో అచ్చువేస్తే ప్రసంగ వ్యాసం. \"జనపదులు – జానపదులు\" పేరిట యువభారతి ప్రచురించిన రేడియో ప్రసంగం.","జానపద కళారూపాలు: యక్షగానం, పగటివేషాలు, తోలుబొమ్మలాట, కురవంజి, బుర్రకథ, కోలాటం, భాగోతాలు.","జానపద సంగీతం = దేశీ సంగీతం; పదాలు, మంగళహారతులు, పాటలు అని విభజన."],"w":[["జానపదులు","పల్లెల్లో నివసించే ప్రజలు"],["సారస్వతం","సాహిత్యం"],["పరికించు","పరిశీలించు"],["లాక్షణిక గ్రంథాలు","శాస్త్ర నియమాలు చెప్పే గ్రంథాలు"],["ఆటపట్టు","నిలయం, స్థానం"],["యక్షగానం","పాడుతూ ఆడే వీథి నాటకం"],["కురువలు","ఒక ఆటవిక జాతి"],["గోధూళి","సాయంత్రం పశువులు ఇంటికి వచ్చే వేళ"],["హృదయంగమం","మనసుకు హత్తుకునేది"],["నిష్ణాతులు","నేర్పరులు"],["దుస్సహం","భరించలేనిది"],["దేశద్రిమ్మరులు","ఊరూరా తిరిగేవారు"],["రసార్ద్రం","రసంతో తడిసినది"],["శుష్కం","ఎండిపోయినది, రసహీనం"],["జక్కులు","యక్షగానాలు ఆడేవారు"]],"gr":{"t":"భాషాంశాలు","p":["ఉపమాలంకారం: ఉపమేయానికి ఉపమానంతో మనోహరమైన పోలిక – \"నెమలివలె, కోకిలవలె జీవితాలు ఉప్పొంగుతుండును\"; \"ధృతరాష్ట్రుని చూచినంత తృప్తి\".","విశేషణ పూర్వపద కర్మధారయ: విశేషణం పూర్వపదం, విశేష్యం ఉత్తరపదం – తెల్లకలువ (తెల్లనైన కలువ), ఉత్తమకళ, నల్లబల్ల.","సంధులు: అతి + అంత = అత్యంత (యణాదేశ); రస + ఆర్ద్రము = రసార్ద్రము (సవర్ణదీర్ఘ); హస్త + ఉదకం = హస్తోదకం (గుణ); ఇంక + ఎప్పుడు = ఇంకెప్పుడు (అకార)."]},"qa":[["జానపదులు అంటే ఎవరు?","పుస్తక విజ్ఞానం, ఆధునిక నాగరికతతో సంబంధం లేకుండా పల్లెల్లో నివసించే ప్రజలు."],["యక్షగానాలు ఎలా పుట్టాయి?","జానపదుల నృత్య సంగీతాల నుండి; వీథుల్లో వేషాలు కట్టి పాడుతూ ఆడేవారు – తర్వాత నాటకాలుగా మారాయి."],["కురవంజి పేరు ఎలా వచ్చింది?","కురువలు అనే ఆటవిక జాతివారు తిరుపతి, శ్రీశైలం వంటి క్షేత్రాల్లో యాత్రికుల కోసం చేసిన నృత్యం కాబట్టి."],["జానపద సంగీతానికి మరో పేరు?","దేశీ సంగీతం."],["జానపద వాద్యాలు?","గజ్జెలు, కొమ్ము, పిల్లనగ్రోవి, నాగస్వరం, అందెలు, తాళాలు, జమిడికలు."],["అంతరించిపోతున్న కళాకారుల తెగలు?","బాలసంతులు, బుడబుక్కలవారు, జంగాలు, దాసరులు, భాగవతులు, పిచ్చుకగుంటులు, వీరముష్టులు."]],"act":"మీ ప్రాంతంలోని జానపద కళారూపాల (కోలాటం, బుర్రకథ, తోలుబొమ్మలాట, హరికథ) వివరాలు, ఫోటోలు సేకరించి ప్రదర్శించండి; జానపద పాటలు సేకరించండి.","kn":"సూక్తి: మనిషి నిద్రలో కనేది కల – మనిషిని నిద్రనుండి మేల్కొలిపేది కళ.","qz":[["\"జానపద నృత్య సంగీతాలు\" రచయిత?","దేవులపల్లి రామానుజరావు","దేవులపల్లి కృష్ణశాస్త్రి","ఇస్మాయిల్","ఉషశ్రీ"],["దేవులపల్లి రామానుజరావు జన్మస్థలం?","దేశాయిపేట (వరంగల్)","మడికొండ","ఆలమూరు","రాఘవంపల్లె"],["ఈ పాఠం ప్రక్రియ?","ప్రసంగ వ్యాసం","కథానిక","ఆత్మకథ","నాటకం"],["ఆంధ్ర సాహిత్య అకాడమీ ప్రథమ కార్యదర్శి?","దేవులపల్లి రామానుజరావు","పల్లా దుర్గయ్య","తిరుమల రామచంద్ర","ఉషశ్రీ"],["దేవులపల్లి రచన?","పచ్చతోరణం","పాలవెల్లి","చెట్టు నా ఆదర్శం","వరవిక్రయం"],["యక్షగానాలు చివరకు ఏమయ్యాయి?","నాటకాలు","సినిమాలు","నవలలు","శతకాలు"],["కురవంజి నృత్యం చేసిన జాతి?","కురువలు","గొల్లలు","జంగాలు","దాసరులు"],["జానపద సంగీతానికి మరో పేరు?","దేశీ సంగీతం","మార్గ సంగీతం","కర్ణాటక సంగీతం","హిందుస్తానీ"],["ప్రసిద్ధ జానపద కథ?","బొబ్బిలి కథ","మనుచరిత్ర","ఆముక్తమాల్యద","వసుచరిత్ర"],["బాలికలకు ప్రియమైన ఆట?","కోలాటం","చదరంగం","క్రికెట్","కబడ్డీ"],["\"గొల్లవారి వాడలకు కృష్ణమూర్తి\" – ఏ ఆటలో పాట?","కోలాటం","తోలుబొమ్మలాట","యక్షగానం","బుర్రకథ"],["యక్షగానాలు ఆడేవారిని ఏమంటారు?","జక్కులు","జంగాలు","దాసరులు","బుడబుక్కలవారు"],["\"నెమలివలె… కోకిలవలె\" – అలంకారం?","ఉపమ","రూపకం","అతిశయోక్తి","అంత్యానుప్రాస"],["\"నల్లబల్ల\" సమాసం?","విశేషణ పూర్వపద కర్మధారయ","ద్వంద్వ","ద్విగు","షష్ఠీ తత్పురుష"]],"wb":{"mis":"ఉపమాలంకారంలో \"వలె, లాగ, వంటి, అంత\" వంటి పోలిక పదాలు ఉంటాయి; రూపకంలో ఉపమేయమే ఉపమానం అని అభేదంగా చెబుతారు.","qz":[["అత్యంత విడదీస్తే?","అతి + అంత (యణాదేశ)","అత్య + అంత","అతి + యంత","అత్ + యంత"],["హస్తోదకం విడదీస్తే?","హస్త + ఉదకం (గుణ)","హస్తో + దకం","హస్త + ఓదకం","హస్తు + ఉదకం"],["రసార్ద్రము విడదీస్తే?","రస + ఆర్ద్రము (సవర్ణదీర్ఘ)","రసా + ర్ద్రము","రస + అర్ద్రము (గుణ)","రసి + ఆర్ద్రము"],["\"ఉన్నతవిద్య\" విగ్రహం?","ఉన్నతమైన విద్య","ఉన్నతము, విద్య","ఉన్నతము యొక్క విద్య","ఉన్నతము కొరకు విద్య"],["\"నిన్ను చూస్తే ధృతరాష్ట్రుని చూచినంత తృప్తి\" – అలంకారం?","ఉపమ","అతిశయోక్తి","వృత్త్యనుప్రాస","యమకం"],["\"ఆటపట్టు\" అంటే?","నిలయం","ఆట","పట్టుదల","ఆటగాడు"]],"pg":"65–73","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":73,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 65)","అవగాహన – ప్రతిస్పందన (పుట 71)","వ్యక్తీకరణ; పదజాలం; అలంకారాలు (పుట 72)","సంధులు, సమాసాలు; ప్రాజెక్టు (పుట 73)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 65)",["1) తెలుగు పల్లెల సౌందర్యం, రైతుల వేషభాషలు, వినోదాలు (తోలుబొమ్మలాట, వీథినాటకాలు), కళాసౌందర్యం 2) రైతుల వేషభాషల్లో (కోరమీసాలు, తలపాగా, ధోవతులు), సామెతలు, లోకోక్తులు, అచ్చ తెలుగు మాటల్లో మన సంస్కృతి ప్రతిబింబిస్తుంది 3) కళలు, సంగీతం గ్రామీణుల జీవితంలో భాగం – పనిలో, పండుగల్లో, వినోదంలో ఆనందం, ఐక్యత ఇస్తాయి 4) తోలుబొమ్మలాటలు, వీథినాటకాలు, పాటలు, నృత్యాలు, హరికథలు పల్లెల్లోనే పుట్టి తరతరాలుగా ప్రజల వల్లనే నిలుస్తున్నాయి కాబట్టి"]],["అవగాహన – ప్రతిస్పందన (పుట 71)",["1. నిజమే – జానపదులు పొలం పనుల్లో, కోతల్లో, పిండి విసురుతూ, ఊయల ఊపుతూ, పండుగల్లో, పెళ్ళిళ్ళలో పాటలు పాడతారు; కోలాటం, కురవంజి వంటి నృత్యాలు చేస్తారు; పాటలు శ్రమను మరిపిస్తాయి – నృత్య సంగీతాలు లేని జానపద జీవితం లేదు","2. శీర్షికలు (ఉదా): \"యక్షగానాలు – కురవంజి – జానపద కథలు\"; \"జానపదులు – సంగీత ప్రియులు\"; \"జానపద పాటల రకాలు\"; \"అంతరించిపోతున్న జానపద కళాకారులు\"","3. ప్రశ్నలు: 1) పల్లెల్లోని ఆటలకూ పాటలకూ ఉన్న సంబంధం ఏమిటి? 2) అందరినీ ఆకర్షించే ఆట ఏది? 3) యక్షగానాలు ఆడేవారిని ఏమంటారు? 4) భాగోతులని ఎవరిని అంటారు? 5) ఇవి దేనికి నిదర్శనాలు?","4. అ) ఆంధ్ర సారస్వత పరిషత్తు రథసారథిగా, ఆంధ్ర సాహిత్య అకాడమీ ప్రథమ కార్యదర్శిగా, పత్రికా సంపాదకుడిగా సేవ చేశారు; ఇరవై గ్రంథాలు రాశారు; సాహిత్య, విద్యా రంగాలకు సేవ చేశారు ఆ) లక్షణ గ్రంథాల నియమాలకు అతీతం; మన సంస్కృతి, దేశీయ సంప్రదాయాలు ప్రతిఫలిస్తాయి; జానపదుల అభిరుచులకు అద్దం; భారత, భాగవత, రామాయణాల ప్రభావం; యక్షగానాలకు జన్మస్థానం ఇ) పొలాల్లో, మంచెలపై రాగాలాపన, పశువులను తోలుకుంటూ పాటలు, విత్తనాలు వేస్తూ, కలుపు తీస్తూ, కోతలు కోస్తూ, పిండి విసురుతూ, వడ్లు దంచుతూ, ఊయల ఊపుతూ, పండుగల్లో, హారతుల్లో పాటలు పాడతారు ఈ) గజ్జెలు, కొమ్ము, పిల్లనగ్రోవి, నాగస్వరం, అందెలు, తాళాలు, జమిడికలు – సహజ వస్తువులతో తయారై, శాస్త్రీయ నియమాలు లేకుండా జీవన సందర్భాలకు అనుగుణంగా వాడతారు"]],["వ్యక్తీకరణ; పదజాలం; అలంకారాలు (పుట 72)",["వ్య.1. అ) ఆధునిక నాగరికత, సినిమా, టీవీ ప్రభావం; కళాకారులకు ప్రోత్సాహం, పోషణ లేకపోవడం; యంత్రాల వల్ల పాటలతో చేసే పనులు తగ్గడం; తరం మారడం – అందుకే ప్రజాసారస్వతం కనుమరుగవుతోంది ఆ) యక్షగానాలు, తోలుబొమ్మలాటలు, హరికథలు, బుర్రకథలు, భాగోతాలు రామాయణ, భారత, భాగవత కథలనే ప్రదర్శించాయి; చదువు రాని పల్లె ప్రజలు కూడా వాటి ద్వారానే ఆ కథలు తెలుసుకున్నారు ఇ) శాస్త్రీయ (మార్గ) సంగీతంలా రాగతాళ నియమాలు లేకుండా దేశంలోని సామాన్య ప్రజల జీవితం నుండి సహజంగా పుట్టింది; జనసామాన్యానికి హృదయంగమం – అందుకే దేశీ సంగీతం","2. వ్యాసం: జానపద నృత్య సంగీతాలు మన సంస్కృతికి ప్రతిబింబాలు. లక్షణ గ్రంథాల నియమాలకు అతీతంగా సహజంగా పుట్టాయి. యక్షగానం, పగటివేషాలు, తోలుబొమ్మలాట, కురవంజి, కోలాటం, బుర్రకథ వంటి కళారూపాలు ఉన్నాయి. పనిపాటల్లో, పండుగల్లో, పెళ్ళిళ్ళలో పాటలు – లాలిపాటలు, జోలపాటలు, ఏలపాటలు, సుద్దులు, అప్పగింత పాటలు. శ్రమను మరిపించి ఆనందం, ఐక్యత ఇస్తాయి. పురాణ కథలను సామాన్యులకు చేర్చాయి. గజ్జెలు, కొమ్ము, డప్పు వంటి వాద్యాలు ప్రత్యేకం. ఇవి అంతరించకుండా కాపాడుకోవాలి","3. ప్రసంగ వ్యాసం: \"సోదర సోదరీమణులారా! జానపద కళలు మన సంస్కృతికి ప్రాణం. వాటిని కాపాడుకోవాలంటే – పాఠశాలల్లో జానపద కళల పోటీలు, ఉత్సవాలు నిర్వహించాలి; కళాకారులకు పింఛన్లు, గౌరవం ఇవ్వాలి; పాటలను రికార్డు చేసి భద్రపరచాలి; పండుగల్లో జానపద ప్రదర్శనలు ఏర్పాటు చేయాలి; టీవీ, సామాజిక మాధ్యమాల్లో ప్రచారం చేయాలి…\"","పదజాలం 1. అ) ఆటపట్టులు – పల్లెలు కళలకు ఆటపట్టులు ఆ) వ్యాప్తిలోకి – సెల్‌ఫోన్లు వేగంగా వ్యాప్తిలోకి వచ్చాయి ఇ) చొచ్చుకొనిపోవు – నీరు భూమిలోకి చొచ్చుకొనిపోయింది ఈ) ప్రఖ్యాతిగాంచు – తిరుపతి లడ్డు ప్రఖ్యాతిగాంచింది","2. అ) జానపదులు – పల్లెల్లో నివసిస్తూ, పుస్తక విజ్ఞానం, ఆధునిక నాగరికతతో సంబంధం లేని సామాన్య ప్రజలు ఆ) పురాణగాథలు – రామాయణ, భారత, భాగవతాది పురాణాల్లోని కథలు ఇ) అప్పగింత పాటలు – పెళ్ళి తర్వాత పెళ్ళికూతురిని అత్తవారింటికి అప్పగించేటప్పుడు పాడే పాటలు","అలంకారాలు అ) ఉపమాలంకారం – ధృతరాష్ట్రుని చూసిన తృప్తితో సంజయుని చూసిన తృప్తిని పోల్చారు ఆ) ఉపమాలంకారం – జానపదుల జీవితాలను నెమలితో, కోకిలతో \"వలె\" అని పోల్చారు. లక్షణం: ఉపమేయానికి ఉపమానంతో మనోహరమైన పోలిక చెప్పడం"]],["సంధులు, సమాసాలు; ప్రాజెక్టు (పుట 73)",["అ) అత్యంత = అతి + అంత (యణాదేశ సంధి) ఆ) రసార్ద్రము = రస + ఆర్ద్రము (సవర్ణదీర్ఘ సంధి) ఇ) ఆస్తులనెల్ల = ఆస్తులను + ఎల్ల (ఉకార సంధి) ఈ) చద్దన్నము = చద్ది + అన్నము (ఇకార సంధి) ఉ) ఇంకెప్పుడు = ఇంక + ఎప్పుడు (అకార సంధి) ఊ) హస్తోదకం = హస్త + ఉదకం (గుణ సంధి)","విశేషణ పూర్వపద కర్మధారయ: అ) ఉత్తమకళ – ఉత్తమమైన కళ ఆ) ఉన్నతవిద్య – ఉన్నతమైన విద్య ఇ) నల్లబల్ల – నల్లనైన బల్ల ఈ) మంచి బాలుడు – మంచివాడైన బాలుడు","ప్రాజెక్టు: మీ ప్రాంత జానపద కళారూపాలు, పాటలు, కళాకారుల వివరాలు సేకరించి నివేదిక"]]]},{"id":"sl9","no":9,"t":"శతక మాధురి","m":[11],"ty":"పద్యం (శతకం)","th":"విలువలు","by":"శతకకవులు","sum":"వివిధ శతకాల నుండి ఏరిన నీతి పద్యాలు ఇవి. వృద్ధుల సేవ చేసేవాడిని బుద్ధిమంతుడు, పవిత్రుడు, ధర్మాత్ముడు అని పెద్దలు పొగడుతారు (కుమార శతకం). గురువును మనసులో నిలుపుకొని పనిచేస్తే తప్పులు తొలగి ధన్యుడై లోకమాన్యుడవుతాడు; \"మాతృదేవో భవ\" – తల్లిని మించిన దైవం లేదు (కాళికాంబ సప్తశతి). అబద్ధమాడనివాడే యోగ్యుడు, శత్రువులకు జంకనివాడే వీరుడు, అడిగినవారికి వెనకాడక ఇచ్చేవాడే దాత, రాముని సేవించేవాడే నిర్భయుడు (దాశరథీ శతకం). సంపదల్లో మహాత్ముల మనసు కలువలా మెత్తగా, ఆపదల్లో కొండలా కఠినంగా (స్థిరంగా) ఉంటుంది (సుభాషిత రత్నావళి). అడవి పక్షులకు, జంతువులకు, చెట్లకు, గర్భంలోని శిశువుకు, పాములకు, తుమ్మెదలకు, పశువులకు ఆహారం ఇచ్చేది నరసింహుడే – జీవకోటిని పోషించే దాత నీవే (నరసింహ శతకం).","pts":["శతకం: వంద (నూరు) పద్యాలకు పైగా గల రచన; ప్రతి పద్యం చివర \"మకుటం\" ఉంటుంది; ఒకే ఛందస్సులో నడుస్తుంది; నీతి, భక్తి, వైరాగ్యాలను బోధిస్తుంది.","పక్కి అప్పల నరసయ్య (16వ శతాబ్దం) – కుమార శతకం, కుమారీ శతకం.","పోతులూరి వీరబ్రహ్మేంద్రస్వామి (17వ శతాబ్దం) – కాళికాంబ సప్తశతి, కాలజ్ఞానం.","కంచెర్ల గోపన్న (రామదాసు, 17వ శతాబ్దం) – దాశరథీ శతకం (\"దాశరథీ కరుణాపయోనిధీ\").","భర్తృహరి (మూలం, 7వ శతాబ్దం) – సుభాషిత త్రిశతి; తెలుగు అనువాదం ఏనుగు లక్ష్మణకవి (18వ శతాబ్దం) – సుభాషిత రత్నావళి.","కాకుత్థం శేషప్పకవి (18వ శతాబ్దం) – నరసింహ శతకం (\"భూషణవికాస! శ్రీధర్మపురనివాస!\"), ధర్మపురి రామాయణం (యక్షగానం).","ఉత్పలమాల: భ ర న భ భ ర వ గణాలు; 4 పాదాలు; యతి 10వ అక్షరం; ప్రాస నియమం ఉంటుంది."],"w":[["బుధులు","పండితులు, పెద్దలు"],["పూతచరితుడు","పవిత్రమైన నడవడి గలవాడు"],["ఇద్ధర","ఈ భూమి"],["ధన్యుడు","కృతార్థుడు"],["లోకమాన్యుడు","లోకం గౌరవించేవాడు"],["శ్రుతులు","వేదాలు"],["స్మృతులు","ధర్మశాస్త్రాలు"],["బొంకు","అబద్ధం"],["అరిబృందం","శత్రుసమూహం"],["జోదు","వీరుడు"],["నిరాతంకం","భయం లేనిది"],["పయోనిధి","సముద్రం"],["ఉత్పలం","కలువ"],["మహీధరం","కొండ"],["మధుపాళి","తుమ్మెదల గుంపు"]],"gr":{"t":"భాషాంశాలు","p":["ఉత్పలమాల లక్షణాలు: 4 పాదాలు; ప్రతి పాదంలో భ ర న భ భ ర వ గణాలు (20 అక్షరాలు); యతి 10వ అక్షరం; ప్రాస నియమం.","యతి: పాదంలోని మొదటి అక్షరం; యతిస్థానంలోని అక్షరంతో దానికి మైత్రి ఉండాలి. ప్రాస: పాదంలోని రెండవ అక్షరం – నాలుగు పాదాల్లోనూ ఒకే హల్లు.","అతిశయోక్తి: \"మా పొలంలో బంగారం పండింది\". షష్ఠీ తత్పురుష: వృద్ధజనసేవ. విశేషణ పూర్వపద కర్మధారయ: మంగళస్నానము.","ప్రకృతి–వికృతి: అటవి–అడవి, విద్య–విద్దె, కథ–కత, సంతోషం–సంతసం, పక్షి–పక్కి, భోజనం–బోనం, పశువు–పసువు, ఆహారం–ఓగిరం."]},"qa":[["వృద్ధుల సేవ చేసేవాడిని పెద్దలు ఏమంటారు?","బుద్ధిమంతుడు, పవిత్రమైన నడవడి గలవాడు, ధర్మాత్ముడు."],["లోకమాన్యులై తరించేవారు?","గురువును మనసులో నిలుపుకొని పనిచేసి తప్పులు తొలగి ధన్యులైనవారు."],["ప్రత్యక్ష దైవం ఎవరు?","తల్లి – \"మాతృదేవో భవ\"."],["గోపన్న ప్రకారం దాత ఎవరు?","అడిగినవారికి వెనకాడకుండా చేయి చాచి ఇచ్చేవాడు."],["మహాత్ముల మనసు ఎలా ఉంటుంది?","సంపదల్లో కలువలా మృదువుగా, ఆపదల్లో కొండలా కఠినంగా (స్థిరంగా)."],["జీవులను పోషించే దాత?","ధర్మపురి నరసింహుడు (భగవంతుడు)."]],"act":"వేమన, సుమతీ, భాస్కర, దాశరథీ శతకాల నుండి నీతి పద్యాలు సేకరించి, భావాలతో పద్యసంకలనం తయారుచేయండి; కంఠస్థం చేసి పద్య పఠన పోటీ నిర్వహించండి.","kn":"సూక్తి: ఆలయం శిథిలమైపోవచ్చు, బావి పూడుకుపోవచ్చు, నీటి ఉద్ధృతికి చెరువు కట్ట తెగిపోవచ్చు, అడవి నశించవచ్చు – కానీ పద్యం అజరామరంగా నిలిచి ఉంటుంది.","qz":[["కుమార శతకం రచయిత?","పక్కి అప్పల నరసయ్య","కంచెర్ల గోపన్న","శేషప్పకవి","వేమన"],["కాళికాంబ సప్తశతి రచయిత?","పోతులూరి వీరబ్రహ్మేంద్రస్వామి","ఏనుగు లక్ష్మణకవి","పక్కి అప్పల నరసయ్య","బద్దెన"],["దాశరథీ శతకం రచయిత?","కంచెర్ల గోపన్న (రామదాసు)","శేషప్పకవి","పోతన","ధూర్జటి"],["సుభాషిత రత్నావళి (తెలుగు) రచయిత?","ఏనుగు లక్ష్మణకవి","భర్తృహరి","ఏనుగు వీరాస్వామి","బద్దెన"],["నరసింహ శతకం మకుటంలో ఉన్న క్షేత్రం?","ధర్మపురి","యాదగిరి","సింహాచలం","మంగళగిరి"],["శతకంలో ప్రతి పద్యం చివర ఉండేది?","మకుటం","యతి","ప్రాస","గణం"],["జీవులకు ప్రత్యక్ష దైవం?","అమ్మ","అక్క","అన్న","రాజు"],["\"దాశరథి\" అంటే?","దశరథుని కుమారుడు రాముడు","దశరథుడు","దశరథుని రథం","లక్ష్మణుడు"],["సంపదల్లో మహాత్ముల మనసు?","కలువలా మృదువు","శిలలా కఠినం","గర్వంగా","భయంగా"],["ఆపదల్లో మహాత్ముల మనసు?","కొండలా కఠినం (స్థిరం)","కలువలా మెత్తన","భయంతో","దుఃఖంతో"],["\"బొంకనివాడే యోగ్యుడు\" – బొంకు అంటే?","అబద్ధం","బలం","భయం","దానం"],["\"మధుపాళి\" అంటే?","తుమ్మెదల గుంపు","తేనెటీగ తుట్టె","పూలదండ","కోయిలలు"],["ఉత్పలమాల గణాలు?","భ ర న భ భ ర వ","న జ భ జ జ జ ర","స భ ర న మ య వ","మ స జ స త త గ"],["ఉత్పలమాల యతిస్థానం?","10వ అక్షరం","11వ అక్షరం","13వ అక్షరం","14వ అక్షరం"]],"wb":{"mis":"ఉత్పలమాలలో యతి 10వ అక్షరం; చంపకమాలలో 11వ అక్షరం – కలపకండి. ప్రాస అంటే పాదంలో రెండవ అక్షరం.","qz":[["పక్షి – వికృతి?","పక్కి","పసువు","విద్దె","బోనం"],["ఆహారం – వికృతి?","ఓగిరం","బోనం","అడవి","కత"],["భోజనం – వికృతి?","బోనం","బోగము","భోజ్యం","బొజ్జ"],["\"మా పొలంలో బంగారం పండింది\" – అలంకారం?","అతిశయోక్తి","ఉపమ","రూపకం","స్వభావోక్తి"],["\"వృద్ధజనుల యొక్క సేవ\" – సమాస పదం?","వృద్ధజనసేవ (షష్ఠీ తత్పురుష)","వృద్ధసేవజన (ద్వంద్వ)","సేవావృద్ధులు (బహువ్రీహి)","వృద్ధజనసేవలు (ద్విగు)"],["పద్య పాదంలో రెండవ అక్షరాన్ని ఏమంటారు?","ప్రాస","యతి","గణం","మకుటం"]],"pg":"74–83","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":82,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 74)","అవగాహన – ప్రతిస్పందన (పుట 79)","పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 80)","పదజాలం (పుట 81)","పదజాలం; వ్యాకరణాంశాలు (పుట 82)","ఉత్పలమాల లక్ష్యలక్షణ సమన్వయం (పుట 83)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 74)",["1) నిజమైన మంచి నీలం (రత్నం) ఒక్కటి చాలు; మెరిసే గాజు రాళ్ళు తట్టెడు ఎందుకు? అలాగే మంచి పద్యం ఒక్కటి చాలు – వేమన 2) \"ఉప్పుకప్పురంబు నొక్కపోలికనుండు…\", \"అనగననగ రాగమతిశయిల్లుచునుండు…\", \"ఎప్పుడు సంపద గలిగిన…\" (సుమతీ) 3) పద్యాలు చిన్నవి, సులువుగా గుర్తుంటాయి; జీవితానికి కావలసిన నీతి, మంచి నడవడిక, మంచి పదజాలం నేర్పుతాయి"]],["అవగాహన – ప్రతిస్పందన (పుట 79)",["1. అ) వృద్ధాశ్రమాల్లో వదిలేసిన తల్లిదండ్రుల వార్తలు; పిల్లలు పట్టించుకోక ఒంటరిగా బాధపడే వృద్ధులు – వారికి ప్రేమ, సేవ, గౌరవం ఇవ్వాలి ఆ) తల్లి మనసు వెన్న వంటిది; పిల్లల కోసం ఏ కష్టమైనా భరిస్తుంది; తాను తినకపోయినా పిల్లలకు పెడుతుంది; నిస్వార్థ ప్రేమ","2. అ) i) అమ్మ ఆ) iii) దశరథుని కుమారుడైన రాముడు ఇ) i) కలువలలాగ మృదువుగా ఈ) iii) నరసింహుడు","3. సరైన క్రమం: ఇ) గడిచిపోయిన క్షణం తిరిగి రాదు → ఈ) కాలాన్ని వ్యర్థంగా గడపకూడదు → అ) దీపమున్నప్పుడే ఇల్లు చక్కదిద్దుకోవాలి → ఆ) కాలం విలువ గుర్తించి చదువుకోవాలి"]],["పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 80)",["అ) గురువును ఏకాగ్రతతో మనసులో ధ్యానిస్తూ పనిచేసి తప్పులు తొలగి ధన్యులైనవారు ఆ) \"మాతృదేవో భవ\" – జీవులకు తల్లే ప్రత్యక్ష దైవం; తల్లిని మించిన దైవం లేదు ఇ) అబద్ధమాడనివాడు ఉత్తముడు (యోగ్యుడు); శత్రువులకు జంకనివాడు ధీరుడు; అడిగినవారికి వెనకాడక ఇచ్చేవాడు దాత; రాముని సేవించేవాడు నిర్భయమైన మనసు గలవాడు ఈ) పెద్ద కొండల వలె కఠినంగా, స్థిరంగా – చలించరు ఉ) నరసింహుడు (భగవంతుడు)","వ్య.అ) 1. గురువు అజ్ఞానమనే చీకటిని తొలగిస్తాడు; సరైన మార్గం చూపుతాడు; తప్పులు సరిదిద్దుతాడు; క్రమశిక్షణ, విలువలు నేర్పుతాడు; గురువును ఆశ్రయిస్తే జీవితంలో విజయం, గౌరవం లభిస్తాయి 2. తల్లి మనకు జన్మనిచ్చి, పాలిచ్చి పెంచుతుంది; మొదటి గురువు; నిస్వార్థంగా ప్రేమిస్తుంది; మన కోసం కష్టాలు భరిస్తుంది – అందుకే దైవంతో సమానం; \"మాతృదేవో భవ\" 3. సంపదలో గర్వించని, ఆపదలో చలించని, సత్యం పలికే, ఇతరులకు సాయపడే వారు మహాత్ములు – గాంధీ, మదర్ థెరిసా, అబ్దుల్ కలాం 4. ఓ ధర్మపురి నరసింహా! అడవి పక్షులకు ఆహారం, జంతువులకు మేత, చెట్లకు నీరు, గర్భంలోని శిశువుకు పోషణ, పాములకు పాలు, తుమ్మెదలకు తేనె, పశువులకు పచ్చిగడ్డి ఇచ్చేది నీవే; జీవకోటిని పోషించే దాత నీవు తప్ప మరొకరు లేరు","ఆ) 1. తల్లిదండ్రులు, గురువులు ప్రత్యక్ష దైవాలు – తల్లి జన్మనిచ్చి పెంచింది; తండ్రి కష్టపడి పోషించాడు, చదివిస్తున్నాడు; గురువు జ్ఞానం ఇస్తున్నాడు; వారు లేకుండా మనం లేం; వారిని గౌరవించి, వృద్ధాప్యంలో సేవ చేయాలి 2. ఉదా: డొక్కా సీతమ్మ – ఆకలితో వచ్చిన ప్రతి ఒక్కరికీ అన్నం పెట్టిన అన్నపూర్ణ; లేదా మా ఊరి పాఠశాలకు భూమి, భవనం ఇచ్చిన దాత – వారి త్యాగం వల్ల ఎందరో చదువుకుంటున్నారు","ఇ) 1. సూక్తులు: \"వృద్ధుల సేవే దేవుని సేవ\"; \"అమ్మను మించిన దైవం లేదు\"; \"గురువును నమ్మినవాడు ధన్యుడు\"; \"సత్యమే యోగ్యత\"; \"సంపదలో వినయం, ఆపదలో ధైర్యం\" 2. మంచి గుణాలు: పెద్దల సేవ, గురుభక్తి, మాతృభక్తి, సత్యం, ధైర్యం, దానగుణం, వినయం, స్థైర్యం, దైవభక్తి, జీవకారుణ్యం"]],["పదజాలం (పుట 81)",["1. శతకాలు: 2) సుమతీ శతకం 3) భాస్కర శతకం 4) కుమార శతకం 5) కుమారీ శతకం 6) దాశరథీ శతకం 7) నరసింహ శతకం 8) శ్రీకాళహస్తీశ్వర శతకం","2. అటవి – అడవి; విద్య – విద్దె; కథ – కత; సంతోషం – సంతసం; పక్షి – పక్కి; భోజనం – బోనం; పశువు – పసువు; ఆహారం – ఓగిరం","3. 1) వృద్ధులు = ముసలివారు – ముసలివారిని గౌరవించాలి 2) యోగ్యుడు = అర్హుడు – రాము బహుమతికి అర్హుడు 3) ఆపదలు = కష్టాలు – కష్టాల్లో మిత్రుని ఆదుకోవాలి 4) దాతలు = దానం చేసేవారు – దానం చేసేవారి వల్ల గ్రంథాలయం వెలిసింది"]],["పదజాలం; వ్యాకరణాంశాలు (పుట 82)",["4. 1) ధన్యులు – తల్లిదండ్రులను సేవించేవారు ధన్యులు 2) మాన్యులు – గురువులు మాన్యులు 3) జంకు – నిజం చెప్పడానికి జంకకూడదు 4) అరిబృందము – సైనికులు అరిబృందాన్ని తరిమికొట్టారు","వ్యా.1. అ) అంత్యానుప్రాస / వృత్త్యనుప్రాస – పాదాంతాల్లో \"వలయు\" మళ్ళీ మళ్ళీ వచ్చింది ఆ) అతిశయోక్తి – పంట బాగా పండిందని ఎక్కువ చేసి చెప్పారు","2. అ) వృద్ధజనసేవ – షష్ఠీ తత్పురుష ఆ) మంగళస్నానము – విశేషణ పూర్వపద కర్మధారయ"]],["ఉత్పలమాల లక్ష్యలక్షణ సమన్వయం (పుట 83)",["ఆపురి (UII – భ) / బాయకుం (UIU – ర) / డుమక (III – న) / రాంకశ (UII – భ) / శాంకమ (UII – భ) / నోజ్ఞమూ (UIU – ర) / ర్తిభా (IU – వ) → భ ర న భ భ ర వ గణాలు వచ్చాయి; యతి: 1వ అక్షరం \"ఆ\" – 10వ అక్షరం \"రాం\" (ఆ–ఆ అచ్చు మైత్రి); ప్రాస: రెండవ అక్షరం \"పు\" (ప). కాబట్టి ఇది ఉత్పలమాల పద్యపాదం","ప్రాజెక్టు: వివిధ శతకాల నీతి పద్యాలు సేకరించి భావాలతో సంకలనం"]]]},{"id":"sl10","no":10,"t":"మాట్లాడే నాగలి","m":[11],"ty":"అనువాద కథ","th":"జీవకారుణ్యం","by":"పొన్‌కున్నం వర్కీ (అను: ఎన్. వేణుగోపాలరావు)","sum":"కేరళ రైతు ఓసెఫ్‌కు తన ఎద్దు \"కన్నన్\" అంటే ప్రాణం – అందరూ అతణ్ణి \"ఎద్దు పిచ్చోడు\" అంటారు. చెర్నాకోల ఎప్పుడూ వాడడు; స్నేహితుడితో మాట్లాడినట్టే దానితో మాట్లాడతాడు. కన్నన్ కూడా అతని మనసు పసిగట్టి పనిచేస్తుంది; గట్లు తెగకుండా జాగ్రత్తగా నడుస్తుంది; అరటి, కొబ్బరి మొలకలు ముట్టదు. ఓసెఫ్ ఆలాపనకు అలసట మరిచి పనిచేసే కన్నన్, సంగీత జ్ఞానం లేని పచన్ పాడితే అతణ్ణి తన్నింది. పన్నెండేళ్ళు పనిచేసిన తర్వాత కూతురు కత్రి పెళ్ళికి మూడువేల కట్నం, ఖర్చుల కోసం పొలం తాకట్టు పెట్టి, కన్నన్‌ను కూడా అమ్మేయాల్సి వచ్చింది – కన్నీళ్ళతో పనసచెట్టు కింద నిలబడ్డాడు. ఈస్టర్ రోజు కూతురికి బట్టలు కొనడానికి కొట్టాయం వెళ్ళిన ఓసెఫ్, మునిసిపాలిటీ మృత్యుముద్ర వేసిన బక్కచిక్కిన ఎద్దుల మధ్య కన్నన్‌ను చూసి గుండె పగిలి కౌగిలించుకున్నాడు. బట్టల డబ్బుతో దాన్ని కొని ఇంటికి తెచ్చాడు. \"నాకు నువ్వెంతో కన్నన్ అంతే\" అని కూతురితో అన్నాడు.","pts":["రచయిత: పొన్‌కున్నం వర్కీ – మలయాళ అభ్యుదయ రచయితల్లో ప్రముఖుడు; స్వాతంత్ర్యోద్యమంలో పాల్గొని జైలుశిక్ష అనుభవించాడు; ఉపాధ్యాయుడిగా జీవితం ప్రారంభించాడు.","1939లో కథా సంకలనంతో రచయితగా పరిచయం; 24 కథా సంపుటాలు, 16 నాటకాలు, 2 కవితా సంపుటాలు, ఆత్మకథ రాశాడు; మానవతావాది.","అనువాదం: ఎన్. వేణుగోపాలరావు (మలయాళం నుండి తెలుగుకు); సాహిత్య అకాడమీ ప్రచురించిన \"భారతీయ సాహిత్యం – సమకాలీన కథానికలు\" గ్రంథం నుండి.","ప్రక్రియ: అనువాద కథ – ఒక భాషలోని విషయాన్ని వేరొక భాషలోకి మార్చి రాయడం అనువాదం.","పాత్రలు: ఓసెఫ్ (రైతు), కన్నన్ (ఎద్దు), మరియా (భార్య), కత్రి (కూతురు), పచన్ (కేలన్ కొడుకు), కటికవాడు.","కథ నేపథ్యం: కేరళ – కొట్టాయం, ఈస్టర్ పండుగ; వరకట్నం, రైతుల పేదరికం, మూగజీవాల పట్ల ప్రేమ."],"w":[["వృషభం","ఎద్దు"],["పసికట్టు","గ్రహించు, గుర్తించు"],["చెర్నాకోల","పశువులను తోలే కర్ర"],["గిట్ట","పశువు కాలి డెక్క"],["అరిష్టం","కీడు"],["ఆలాపన","పదాలు లేకుండా రాగం తీయడం"],["కాపడం","వేడి కాపు"],["క్రయపత్రం","అమ్మకం పత్రం"],["తాకట్టు","కుదువ"],["గత్యంతరం","మరో దారి"],["నిష్ఫలత్వం","ఫలితం లేకపోవడం"],["దీక్షాదినాలు","ఉపవాస దినాలు (లెంట్)"],["మృత్యుముద్ర","చంపడానికి వేసే గుర్తు"],["డగ్గుత్తిక","గొంతు పూడుకుపోవడం"],["ఠికాణా","నివాసం, చిరునామా"]],"gr":{"t":"భాషాంశాలు","p":["అవ్యయీభావ సమాసం: యథాశక్తి – శక్తిననుసరించి. ద్వంద్వ సమాసం: తల్లిదండ్రులు – తల్లియు, తండ్రియు.","ఉపమాలంకారం: \"మేఘగర్జన విని పురివిప్పిన నెమలిలా అది ఆనందించేది\".","ఉత్పలమాల (దాశరథీ పద్యం): కొంకని / వాండెదా / తమిముఁ / గొల్చిభ / జించిన / వాండెపో / నిరా = భ ర న భ భ ర వ; యతి: కొ – గొ (10వ అక్షరం); ప్రాస: \"ంక\"."]},"qa":[["ఓసెఫ్‌ను ఇతర రైతులు ఏమని పిలిచేవారు?","\"ఎద్దు పిచ్చోడు\"."],["ఓసెఫ్ కన్నన్‌తో ఎలా మాట్లాడేవాడు?","స్నేహితుడితో మాట్లాడినట్టే – ఎప్పుడూ కొట్టడు, తిట్టడు."],["కన్నన్ వేటిని తొక్కడం ఘోరం అనుకుంది?","శ్రద్ధతో నాటిన అరటి చెట్లు, కొబ్బరి మొలకలు."],["పచన్ పాడితే ఏమైంది?","కన్నన్ అసంతృప్తితో తల ఊపి, చివరకు అతని కుడికాలిపై తన్నింది – మూడు రోజులు కాపడం పెట్టుకున్నాడు."],["ఓసెఫ్ కన్నన్‌ను ఎందుకు అమ్మాడు?","కూతురు పెళ్ళికి కట్నం (మూడువేలు), పెళ్ళి ఖర్చుల కోసం."],["కథ ముగింపు?","కసాయి చేతిలో ఉన్న కన్నన్‌ను బట్టల డబ్బుతో కొని ఇంటికి తెచ్చాడు – \"నాకు నువ్వెంతో కన్నన్ అంతే\"."]],"act":"పెంపుడు జంతువులు యజమాని నిర్లక్ష్యంతో పడే బాధలను సంభాషణ రూపంలో రాసి, ఆయా జంతువుల మాస్కులతో కొరియోగ్రఫీ చేసి ప్రదర్శించండి.","kn":"సూక్తి: కపట మానవప్రేమకన్నా కల్మషం లేని మూగజీవుల అనుబంధం మిన్న. జంతు హింస నివారణ చట్టం – 1960.","qz":[["\"మాట్లాడే నాగలి\" మూల రచయిత?","పొన్‌కున్నం వర్కీ","తకళి శివశంకర పిళ్ళై","ఎం.టి. వాసుదేవన్ నాయర్","బషీర్"],["ఈ కథ మూల భాష?","మలయాళం","తమిళం","కన్నడం","హిందీ"],["తెలుగులోకి అనువదించినది?","ఎన్. వేణుగోపాలరావు","ఉషశ్రీ","తిరుమల రామచంద్ర","ఇస్మాయిల్"],["ఈ పాఠం ప్రక్రియ?","అనువాద కథ","నాటకం","ఆత్మకథ","వ్యాసం"],["ఓసెఫ్ ఎద్దు పేరు?","కన్నన్","కుట్టప్పన్","పచన్","కేలన్"],["ఓసెఫ్ భార్య?","మరియా","కత్రి","సారా","మేరీ"],["కన్నన్ తన్నినది ఎవరిని?","పచన్","ఓసెఫ్","కటికవాడు","కత్రి"],["ఓసెఫ్ దగ్గర కన్నన్ ఎన్నేళ్ళు పనిచేసింది?","పన్నెండేళ్ళు","ఐదేళ్ళు","ఇరవై ఏళ్ళు","మూడేళ్ళు"],["ఓసెఫ్ ఎద్దులను ఎందుకు అమ్మాడు?","కూతురు పెళ్ళి కట్నం, ఖర్చులు","అప్పు తీర్చడానికి","ఇల్లు కట్టడానికి","వ్యాపారం కోసం"],["ఓసెఫ్ ఏ పండుగ రోజు కొట్టాయం వెళ్ళాడు?","ఈస్టర్","క్రిస్మస్","ఓణం","సంక్రాంతి"],["ఎద్దులపై \"నల్లని మృత్యుముద్ర\" వేసినది?","మునిసిపాలిటీ","రైతులు","కసాయి","పోలీసులు"],["\"అరిష్టం\" అంటే?","కీడు","అదృష్టం","ఆహారం","ఆరోగ్యం"],["\"నాకు నువ్వెంతో కన్నన్ అంతే\" – ఎవరితో?","కూతురు కత్రితో","భార్య మరియాతో","పచన్‌తో","కటికవాడితో"],["\"క్రయపత్రం\" అంటే?","అమ్మకం/కొనుగోలు పత్రం","ఉత్తరం","రసీదు","పెళ్ళి పత్రిక"]],"wb":{"mis":"అవ్యయీభావంలో పూర్వపదం అవ్యయం (యథా, ప్రతి, ఆ); ద్వంద్వంలో రెండు పదాల అర్థం సమానంగా ప్రధానం. ఉత్పలమాల యతి 10వ అక్షరం.","qz":[["\"పసికట్టు\" అంటే?","గ్రహించు","పట్టుకొను","కట్టివేయు","తినిపించు"],["\"గత్యంతరం\" అంటే?","మరో దారి","గతించిన కాలం","దూరం","ప్రయాణం"],["\"అసహనం\" అంటే?","ఓర్పు లేకపోవడం","సహాయం","సంతోషం","భయం"],["ద్వంద్వ సమాసానికి ఉదాహరణ?","తల్లిదండ్రులు","యథాశక్తి","నల్లబల్ల","పంచపాండవులు"],["అవ్యయీభావ సమాసానికి ఉదాహరణ?","యథాశక్తి","రాగద్వేషాలు","ముక్కంటి","మంచి బాలుడు"],["\"కొంకనివాండెదాత\" – మొదటి గణం?","భ గణం (UII)","ర గణం","న గణం","మ గణం"]],"pg":"84–93","f":"books/10/Class10_Telugu_SecondLanguage_Textbook.pdf","p":92,"lb":"పాఠ్యపుస్తకం","ws":["చదవండి – ఆలోచించండి – చెప్పండి (పుట 84)","అవగాహన – ప్రతిస్పందన (పుట 91)","పేరా ప్రశ్నలు; పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 92)","పదజాలం; వ్యాకరణాంశాలు; ప్రాజెక్టు (పుట 93)"]},"tg":[["చదవండి – ఆలోచించండి – చెప్పండి (పుట 84)",["1) భూమిపై ప్రతి జీవికీ (పక్షి, ఈగ, తేనెటీగ, చీమ…) ప్రాధాన్యం ఉంది; మనిషి తన తెలివిని జీవవైవిధ్య వినాశనానికి వాడుతున్నాడు – దాని గురించి 2) ఇతర జీవులను, జీవవైవిధ్యాన్ని, సకల వనరులను నాశనం చేస్తున్నారు 3) అవి అంతరించిపోయే ప్రమాదంలో ఉన్నాయి; మనిషి మనుగడే అయోమయంలో పడింది 4) చెట్లు నాటాలి, అడవులు నరకకూడదు, జంతువులను హింసించకూడదు, కాలుష్యం తగ్గించాలి, వనరులను పొదుపుగా వాడాలి"]],["అవగాహన – ప్రతిస్పందన (పుట 91)",["1. అ) ఓసెఫ్ అనే రైతుకు కన్నన్ అనే ఎద్దు అంటే ప్రాణం. దానితో స్నేహితుడిలా మాట్లాడేవాడు. కూతురు పెళ్ళి కోసం దాన్ని అమ్మేశాడు. ఈస్టర్ రోజు కసాయి చేతిలో చావుకు సిద్ధంగా ఉన్న కన్నన్‌ను చూసి, కూతురి బట్టల డబ్బుతో కొని ఇంటికి తెచ్చాడు ఆ) సరైనదే – నాగలికి ప్రతీక అయిన కన్నన్ మనిషిలా యజమాని మాటలు అర్థం చేసుకుంది, భావాలు వ్యక్తం చేసింది (నోటితో కాదు, హృదయంతో ఏడ్చింది); రైతు–ఎద్దు–నాగలి అనుబంధమే కథకు ప్రాణం","2. \"మళ్ళీ ఒకసారి దాని చెవుల్లో జీవితం ప్రతిధ్వనించింది\" – ఓసెఫ్ కసాయి దగ్గర కన్నన్‌ను గుర్తుపట్టి పిలిచిన పేరా; \"అది తన నోటితో కాదు, హృదయంతో ఏడ్చింది\" – ఓసెఫ్ దాన్ని కౌగిలించుకున్న పేరా (పుటలు 89–90)"]],["పేరా ప్రశ్నలు; పాఠ ప్రశ్నలు; వ్యక్తీకరణ (పుట 92)",["3. అ) ప్రాణులపై దయ చూపడం ఆ) బియ్యపు పిండితో ముగ్గు పెట్టి చీమలకు ఆహారం వేయడం ఇ) పెద్దలు నిర్ణయించిన ఆచారాలన్నీ జీవకారుణ్యంతో కూడినవి కాబట్టి ఈ) \"ముగ్గు – జీవకారుణ్యం\" ఉ) ముగ్గు, బియ్యపుపిండి, రాతిముగ్గు, చీమలు, జీవకారుణ్యం (ధనుర్మాసం)","4. అ) స్నేహితుడితో మాట్లాడినట్లే – ప్రేమగా, ఎప్పుడూ తిట్టకుండా, కొట్టకుండా (\"ఓ క్షణం ఆగు, పాన్ వేసుకోనీ\") ఆ) శ్రద్ధతో, శ్రమతో నాటిన అరటి చెట్లు, కొబ్బరి మొలకలు ఇ) దొడ్లో పశువులు మేతకు మాడితే ఆ ఇంటికి అరిష్టం దాపురిస్తుంది ఈ) కన్నన్ అసంతృప్తితో తల ఊపి నిరసన తెలిపింది; పచన్ ఆపకపోవడంతో అతని కుడికాలిపై బలంగా తన్నింది – మూడు రోజులు ఇంట్లో కాపడం పెట్టుకున్నాడు","వ్య.1. అ) కన్నన్‌లా యజమానికి విశ్వాసంగా, కష్టపడి పనిచేస్తాను; యజమాని అమ్మినా అతని పరిస్థితి అర్థం చేసుకుంటాను; మళ్ళీ కలిసినప్పుడు ప్రేమతో దగ్గరవుతాను ఆ) ఉపన్యాసాలు ఇచ్చేవారు ఆచరణలో ఏమీ చేయరు; పశువుల కోసం మేత భూములు వదలరు; మాటలతో పశువులను రక్షించలేమని, ఆచరణ కావాలని ఓసెఫ్ ఉద్దేశం ఇ) క్రయపత్రం = అమ్మకం/కొనుగోలు ఒప్పంద పత్రం; భూమి, ఇల్లు, పశువులు, వాహనాలు అమ్మినప్పుడు, కొన్నప్పుడు రాసుకుంటారు ఈ) తన బట్టల కోసం తెచ్చిన డబ్బుతో ఎద్దును కొనుక్కొచ్చావా అనే నిరాశ, కోపం, బాధ ఉ) ముగింపు (ఉదా): కత్రి తండ్రి మనసు అర్థం చేసుకుంది; \"నాకు బట్టలు వద్దు నాన్నా, కన్నన్ బతికింది చాలు\" అంది. కన్నన్ మిగిలిన రోజులు ఆ ఇంట్లోనే ప్రేమగా గడిపింది","2. అ) కన్నన్ పన్నెండేళ్ళు ఓసెఫ్ కుటుంబాన్ని పోషించింది; అతని మనసు అర్థం చేసుకునేది; స్నేహితుడిలా, బిడ్డలా పెరిగింది; అతని చెమటను నాకి ప్రేమ చూపేది; పంటలు పండించి ఇంటికి సంపద తెచ్చింది – అందుకే కన్నకూతురితో సమానంగా చూశాడు ఆ) మూగజీవాలు మాట్లాడలేవు కానీ ప్రేమను గుర్తిస్తాయి; మనకు పాలు, శ్రమ, రక్షణ ఇస్తాయి; ప్రకృతి సమతుల్యతకు అవసరం; వాటికీ బాధ, సంతోషం ఉంటాయి; జీవకారుణ్యం మానవ ధర్మం; చట్టం కూడా జంతుహింసను నిషేధిస్తుంది","3. కథ (ఉదా): \"మూగజీవులకు నోరొస్తే…\" – ఒక రోజు మా ఆవు \"అమ్మా, నా దూడకు పాలు మిగల్చండి\" అంది; కుక్క \"రాత్రంతా కాపలా కాస్తా, ఒక్క రొట్టె ముక్క ఇవ్వండి\" అంది; పక్షులు \"చెట్లు నరకకండి, మా ఇళ్ళు పోతున్నాయి\" అన్నాయి… అప్పటి నుండి మేం అన్ని జీవులనూ ప్రేమగా చూస్తున్నాం"]],["పదజాలం; వ్యాకరణాంశాలు; ప్రాజెక్టు (పుట 93)",["1. అ) పసికట్టు = గ్రహించు – దొంగ ఎత్తుగడను పోలీసులు పసికట్టారు ఆ) అరిష్టం = కీడు – మూఢనమ్మకాలు నమ్మితే కీడే జరుగుతుంది ఇ) మునిగిపోవు = లీనమగు – రాము చదువులో మునిగిపోయాడు ఈ) అసహనం = ఓర్పు లేకపోవడం – అసహనంతో పనులు చెడిపోతాయి ఉ) గత్యంతరం = మరో దారి – వర్షం వల్ల గత్యంతరం లేక బడిలో ఉండిపోయాం","2. అ) మడి/మడిచెక్క = గట్లతో విభజించిన పొలం భాగం – మడిలో నీరు పెట్టారు ఆ) ఆలాపన = పదాలు లేకుండా రాగం తీయడం – గాయకుడు ఆలాపనతో పాట మొదలుపెట్టాడు ఇ) బృందగానం = కలిసి పాడటం – పాఠశాలలో బృందగానం పోటీ జరిగింది ఈ) ఠికాణా = నివాసం, చిరునామా – మిత్రుడి ఠికాణా దొరికింది","వ్యా.1. అ) అవ్యయీభావ – యథాశక్తి: శక్తిననుసరించి (ప్రతిదినము: దినము దినము) ఆ) ద్వంద్వ – తల్లిదండ్రులు: తల్లియు, తండ్రియు (రామలక్ష్మణులు: రాముడును, లక్ష్మణుడును)","2. కొంకని (UII భ) / వాండెదా (UIU ర) / తమిముఁ (III న) / గొల్చిభ (UII భ) / జించిన (UII భ) / వాండెపో (UIU ర) / నిరా (IU వ); తంకమ (UII భ) / నస్కుడె (UIU ర) / న్నగను (III న) / దాశర (UII భ) / థీకరు (UII భ) / ణాపయో (UIU ర) / నిధీ (IU వ) → ఉత్పలమాల. యతి: 1వ పాదం కొ – గొ (క, గ వర్గ మైత్రి), 2వ పాదం తం – దా (త, ద వర్గ మైత్రి); ప్రాస: \"ంక\" (కొంకని, తంక)","ప్రాజెక్టు: పెంపుడు జంతువుల బాధలపై సంభాషణ రాసి, మాస్కులతో ప్రదర్శన"]]]}];
